# One explicitly inspected war paragraph per volume. For several volumes the
# first marked paragraph was not an actual conflict, so select the first actual
# operation by a small, checked allowlist.
WAR_IDS = {
241:'v241-y-819-p0',242:'v242-y-821-p0',243:'v243-y-823-p0',244:'v244-y-829-p2',
245:'v245-y-834-p9',246:'v246-y-838-p0',247:'v247-y-843-p0',248:'v248-y-844-p1',
249:'v249-y-850-p2',250:'v250-y-860-p0',251:'v251-y-868-p0',252:'v252-y-870-p1',
253:'v253-y-877-p0',254:'v254-y-880-p2',255:'v255-y-882-p0',256:'v256-y-884-p0',
257:'v257-y-887-p1',258:'v258-y-889-p1',259:'v259-y-892-p1',260:'v260-y-895-p1',
261:'v261-y-897-p0',262:'v262-y-900-p0',263:'v263-y-902-p0',264:'v264-y-903-p1',
265:'v265-y-904-p2',266:'v266-y-907-p0',267:'v267-y-908-p1',268:'v268-y-911-p2',
269:'v269-y-913-p0',270:'v270-y-917-p0'
}

candidates = json.loads(SRC.read_text())
byid = {x['id']: x for x in candidates}
assert len(DECISIONS) == 86, len(DECISIONS)
assert all(i in byid for i in DECISIONS)
assert all(i in byid for i in WAR_IDS.values())

events, excluded = [], []
reviewed = set()

def quote_for(x):
    d = json.loads((ROOT / f"dist/volume{x['volume']}.json").read_text())
    y = next(y for y in d['years'] if y['year'] == x['year'])
    p = y['paragraphs'][x['anchor']]['plain']
    assert x['text'] in p or p in x['text'], (x['id'], len(x['text']), len(p))
    # Use a stable, exact source substring from the beginning of the paragraph.
    return p[:min(88, len(p))]

for ident, decision in DECISIONS.items():
    x = byid[ident]; reviewed.add(ident)
    if decision is None:
        excluded.append({'candidateId': ident, 'reason': '已读原段：此处为军中缺粮/疫病、战时天气、追叙评论或未发生的设想，不构成该年社会性灾荒饥馑事件。' if any(k in x['text'] for k in ['军','贼','兵','军士','战','先是','昔','若','欲']) else '已读原段：候选触发词只是背景或评议，未记载该年实际发生且符合口径的灾荒、饥馑。'})
        continue
    cats, title = decision
    events.append({'id': ident, 'year': x['year'], 'categories': cats, 'title': title,
        'sources': [{'volume': x['volume'], 'year': x['year'], 'anchor': x['anchor'], 'quote': quote_for(x)}],
        'status': 'reviewed', 'reason': '逐段阅读候选原文及同年上下文；按本年实际发生的民生灾害/饥荒事件归类。'})

for v, ident in WAR_IDS.items():
    x = byid[ident]
    if ident in reviewed: continue
    reviewed.add(ident)
    if v in {243,244,248,249,251,252,254,257,258,259,264,266,270}:
        excluded.append({'candidateId': ident, 'reason': '已逐段检查本卷首个战争候选：该段记载的是赐赏、党争、军政建议/任命或尚未实施的军事部署，未记载该年具体已发生的战事。'})
        continue
    # A paragraph may mention background, but these chosen anchors record
    # explicit implemented military operations in the stated year.
    title = x.get('titles', [''])[0] or x['text'][:32]
    events.append({'id': ident, 'year': x['year'], 'categories': ['war'], 'title': title,
        'sources': [{'volume': x['volume'], 'year': x['year'], 'anchor': x['anchor'], 'quote': quote_for(x)}],
        'status': 'reviewed', 'reason': '逐段阅读原文及同年上下文；本段记载已实施的出兵、攻守、兵变或战斗。'})

# Split distinct same-paragraph incidents instead of treating a whole paragraph
# as one event. Their citations point to the exact clause that records each act.
def split_event(candidate_id, parts):
    pos = next(i for i,e in enumerate(events) if e['id'] == candidate_id)
    base = events.pop(pos)
    for suffix, title, cue in reversed(parts):
        e = dict(base)
        e['id'] = candidate_id + suffix
        e['title'] = title
        e['sources'] = [dict(base['sources'][0], quote=cue)]
        e['reason'] = '逐段阅读原文及同年上下文；同一段落包含多个分别记载的本年事件，按事件拆分。'
        events.insert(pos, e)

split_event('v241-y-819-p0', [
 ('-a','李听袭取海州东海、朐山、怀仁等县','李听袭海州，克东海、朐山、怀仁等县。'),
 ('-b','李愬在沂州击败平卢兵并攻取丞县','李愬败平卢兵于沂州，拔丞县。')])
