BATCH_258Z = {
'v262-y-901-p38': ('朱全忠大举发兵自大梁出征','朱全忠大举兵发大梁。'),
'v262-y-901-p39': ('李神福在青山设伏击败顾全武并俘获之','神福命勿追，暮遣羸兵先行，神福为殿，使行营都尉吕师造伏兵青山下。全武素轻神福，出兵追之；神福、师造夹击，大破之，斩首五千级，生擒全武。'),
'v262-y-901-p40': ('韩全诲派兵劫持昭宗并逼其西赴凤翔','丁酉，令李继筠、李彦弼等勒兵劫上，请幸凤翔，宫禁诸门皆增兵防守，人及文书出入搜阅甚严。'),
'v262-y-901-p43': ('李继筠部掠夺内库，韩全诲遣送诸王宫人赴凤翔','丁未，神策都指挥使李继筠遣部兵掠内库宝货、帷帐、法物，韩全诲遣人密送诸王、宫人先之凤翔。'),
'v262-y-901-p45': ('神策军封锁宫门并在京城大掠','李继筠等勒兵阙下，禁人出入，诸军大掠。'),
'v262-y-901-p46': None,
'v262-y-901-p47': ('韩全诲等逼昭宗携皇室离宫西赴凤翔并纵火焚宫','全诲等逼上下楼，上行纔及寿春殿，李彦弼已于御院纵火。是日冬至，上独坐思政殿，翘一足，一足蹋阑干，庭无群臣，旁无侍者。顷之，不得已，与皇后、妃嫔、诸王百余人皆上马，恸哭声不绝，出门，回顾禁中火已赫然。是夕，宿鄠县。'),
'v262-y-901-p48': None,
'v262-y-901-p50': ('朱全忠进逼华州，杀李巨川并迫使韩建离镇','全忠闻建有表劝天子幸凤翔，乃引兵逼其城。建单骑迎谒，全忠责之，对曰：「建目不知书，凡表章书檄，皆李巨川所为。」全忠以巨川常为建画策，斩之军门。谓建曰：「公许人，可即往衣锦。」丁巳，以建为忠武节度使，理陈州，以兵援送之。'),
'v262-y-901-p52': None,
'v262-y-901-p53': ('朱全忠率军进入长安，李继昭献出所部八千人','朱全忠至长安，宰相百官班迎于长乐坡；明日行，复班辞于临皋驿。全忠赏李继昭之功，初令权知匡国留后，复留为两街制置使，赐与甚厚；继昭尽献其兵八千人。'),
'v262-y-901-p54': ('康怀贞在武功击破凤翔军','茂贞遣其将符道昭屯武功以拒全忠，癸亥，全忠将康怀贞击破之。'),
'v262-y-901-p56': ('朱全忠率军进至凤翔城东，随后移兵北趋邠州','戊辰，朱全忠至凤翔，军于城东。李茂贞登城谓曰：「天子避灾，非臣下无礼；谗人误公至此。」全忠报曰：「韩全诲劫迁天子，今来问罪，迎扈还宫。岐王苟不预谋，何烦陈谕！」上屡诏全忠还镇，全忠乃拜表奉辞。辛未，移兵北趣邠州。'),
'v262-y-901-p58': ('朱全忠攻邠州，李继徽请降并仍镇其地','乙亥，朱全忠攻邠州，丁丑，静难节度使李继徽请降，复姓名杨崇本。全忠质其妻于河中，令崇本仍镇邠州。'),
'v262-y-901-p59': ('李嗣昭率五千骑在平阳北击败汴军','克用遗李嗣昭将五千骑自沁州趣晋州，与汴兵战于平阳北，破之。'),
}
assert set(BATCH_258Y).issubset(byid)
assert set(BATCH_258Z).issubset(byid)
BATCH_258AA = {
'v262-y-901-p60': ('朱全忠攻降盩厔并屠城，强令京城居民迁往华州','己丑，全忠遣朱友宁攻盩厔，不下。戊戌，全忠自往督战，盩厔降，屠之。全忠令崔胤帅百官及京城居民悉迁于华州。'),
'v262-y-901-p61': None,
'v262-y-901-p62': ('李神福围攻临安并以诈营迫使钱镠求和','李神福知钱镠定不死，而临安城坚，久攻不拔，欲归，恐为镠所邀，乃遣人守卫镠祖考丘垄，禁樵采，又使顾全武通家信；镠遣使谢之。神福于要路多张旗帜为虚寨，镠以为淮南兵大至，遂请和；神福受其犒赂而还。'),
'v262-y-901-p63': ('王建派五万兵声称迎驾、实际袭取凤翔山南诸州','建外修好于全忠，罪状李茂贞，而阴劝茂贞坚守，许之救援；以武信节度使王宗佶、前东川节度使王宗涤等为扈驾指挥使，将兵五万，声言迎车驾，其实袭茂贞山南诸州。'),
'v262-y-901-p64': ('天火焚烧抚州城，危全讽投降钟传','江西节度使锺传将兵围抚州刺史危全讽，天火烧其城，士民讙惊。诸将请急攻之，传曰：「乘人之危，非仁也。」乃祝曰：「全讽之罪，无为害民。」火寻止。全讽闻之，谢罪听命，以女妻传子匡时。'),
'v263-y-902-p3': None,
'v263-y-902-p4': ('李嗣昭等攻取慈、隰、绛州并在蒲县击破汴军','李嗣昭等攻慈、隰，下之，进逼晋、绛。己丑，全忠遣兄子友宁将兵会晋州刺史氏叔琮击之。李嗣昭袭取绛州，汴将康怀英复取之。嗣昭等屯蒲县；乙未，汴军十万营于蒲南，叔琮夜帅众断其归路而攻其垒，破之，杀获万余人。'),
'v263-y-902-p5': ('西川军进抵利州，李继忠弃镇逃往凤翔','西川兵至利州，昭武节度使李继忠弃镇奔凤翔；王建以剑州刺史王宗伟为利州制置使。'),
'v263-y-902-p7': ('氏叔琮、朱友宁击溃李嗣昭、周德威军并俘获李克用之子','氏叔琮、朱友宁进攻李嗣昭、周德威营。时汴军横陈十里，而河东军不过数万，深入敌境，众心忷惧。德威出战而败，密令嗣昭以后军前去，德威寻引骑兵亦退。叔琮、友宁长驱乘之，河东军惊溃，禽克用子廷鸾，兵仗辎重委弃略尽。'),
'v263-y-902-p8': ('汴军攻取慈、隰、汾州并围攻晋阳','李克用闻嗣昭等败，遣李存信以亲兵逆之，至清源，遇汴军，存信走还晋阳；汴军取慈、隰、汾三州。辛酉，汴军围晋阳，营于晋祠，攻其西门。'),
'v263-y-902-p9': None,
'v263-y-902-p10': ('李嗣昭、李嗣源夜袭氏叔琮营，并收复慈、隰、汾州','李嗣昭、李嗣源数将敢死士夜入氏叔琮营，斩首捕叔琮留数马及旌旗于高冈之巅。嗣昭等以为有伏兵，乃引去，复取慈、隰、汾三州。'),
'v263-y-902-p11': None,
'v263-y-902-p12': None,
'v263-y-902-p14': None,
}
assert set(BATCH_258AA).issubset(byid)
BATCH_258AB = {
'v263-y-902-p16': None,
'v263-y-902-p19': ('康怀贞在莫谷击败凤翔军李继昭','汴将康怀贞击凤翔将李继昭于莫谷，大破之。'),
'v263-y-902-p22': None,
'v263-y-902-p25': None,
'v263-y-902-p26': ('冯弘铎率水军袭击宣州，田頵在葛山击败之','弘铎将冯晖、颜建说弘铎先击頵，弘铎从之，帅众南上，声言攻洪州，实袭宣州也。杨行密使人止之；不从。辛巳，頵帅舟师逆击于葛山，大破之。'),
'v263-y-902-p27': ('李茂贞出兵与朱全忠战于虢县北而大败','甲申，李茂贞大出兵，自将之，与朱全忠战于虢县之北，大败而还，死者万余人。'),
'v263-y-902-p28': None,
'v263-y-902-p34': ('朱全忠军击退三原援军李茂勋部','保大节度使李茂勋将兵屯三原，救李茂贞；朱全忠遣其将康怀贞、孔勍击之，茂勋遁去。'),
'v263-y-902-p35': None,
'v263-y-902-p36': ('徐绾率部众叛乱，焚掠杭州外城并进逼牙城','镠如衣锦军，命武勇右都指挥使徐绾帅众治沟洫；镇海节度副使成及闻士卒怨言，白镠请罢役，不从。甲戌，镠临飨诸将，绾谋杀镠于座，不果，称疾先出。镠怪之，丁亥，命绾将所部兵先还杭州。及外城，纵兵焚掠。武勇左都指挥使许再思以迎候兵与之合，进逼牙城。'),
'v263-y-902-p38': ('李茂贞夜袭奉天并在与朱全忠交战后败退','庚戌，李茂贞出兵夜袭奉天，虏汴将倪章、邵棠以归。乙未，茂贞大出兵，与朱全忠战，不胜；暮归，汴兵追之，几入西门。'),
'v263-y-902-p40': ('王宗播等攻取兴元外围四寨，继而攻克兴元城','西川兵请假道于兴元，山南西道节度使李继密遣兵戍三泉以拒之；辛丑，西川前锋将王宗播攻之，不克，退休山寨。亲吏柳修业谓宗播曰：「公举族归人，不为之死战，何以自保﹖」宗播令其众曰：「吾与汝曹决战，取功名；不尔，死于此！」遂破金牛、黑水、西县、褒城四寨。军校秦承厚攻西县，矢贯左目，达于右目，镞不出。王建自舐其创，脓溃镞出。王宗播攻马盘寨，继密战败，奔还汉中。西川军乘胜至城下，王宗涤帅众先登，遂克之，继密请降，迁于成都；得兵三万，骑五千，宗涤入屯汉中。'),
'v263-y-902-p41': None,
'v263-y-902-p42': ('朱全忠设伏诱李茂贞出城，击溃凤翔军并促成议和','全忠患李茂贞坚壁不出，季昌请以谲计诱致之。募有能入城为谍者，骑士马景请行，曰：「此行必死，愿大王录其妻子。」全忠恻然止之，景不可。时全忠遣朱友伦发兵于大梁，明日将至，当出兵迓之。景请因此时给骏马杂众骑而出，全忠从之，命诸军皆秣马饱士。丁未旦，偃旗帜潜伏，营中寂如无人。景与众骑皆出，忽跃马西去，诈为逃亡，入城告茂贞曰：「全忠举军遁矣，独留伤病者近万人守营，今夕亦去矣，请速击之！」于是茂贞开门，悉众攻全忠营；全忠鼓于中军，百营俱出，纵兵击之，又遣数百骑据其城门，凤翔军进退失据，自蹈藉，杀伤殆尽。茂贞自是丧气，始议与全忠连和，奉车驾还京，不复以诏书勒全忠还镇矣。'),
}
assert set(BATCH_258AB).issubset(byid)
BATCH_258AC = {
'v263-y-902-p17': None,
'v263-y-902-p44': None,
'v263-y-902-p47': None,
'v263-y-902-p48': ('田頵率军围断杭州交通，陈璋出兵击退其军并夺取营地','頵筑垒绝往来之道，镠患之，募能夺其地者赏以州。衢州制置使陈璋将卒三百出城奋击，遂夺其地，镠即以为衢州刺史。'),
'v263-y-902-p51': ('王建攻取兴州并任命刺史','王建攻拔兴州，以军使王宗浩为兴州刺史。'),
'v263-y-902-p52': ('李茂贞部将彦询、李彦韬先后率兵投奔汴军','戊寅夜，李茂贞假子彦询帅三团步兵奔于汴军；己卯，李彦韬继之。'),
'v263-y-902-p54': ('凤翔军进攻汴军城西寨失败，汴军招降并接纳逃散士卒','癸巳，茂贞复出兵击汴军城西寨，败还。全忠以绛袍衣降者，使招呼城中人，凤翔军夜缒去及因樵采去不返者甚众。是后茂贞或遣兵出击汴军，多不为用，散还。'),
'v263-y-902-p57': ('汴军攻取坊州并攻陷鄜州，俘获留守李继褄','朱全忠遣其将孔勍、李晖将兵乘虚袭鄜、坊；壬子，拔坊州。甲寅，大雪，汴军冒之夕进，五鼓，抵鄜州城下。鄜人不为备，汴军入城，城中兵尚八千人，格鬬至午，鄜人始败，擒留守李继褄。'),
'v263-y-902-p58': ('凤翔城中粮尽并发生大规模饥馑与冻饿死亡','是冬，大雪，城中食尽，冻馁死者不可胜计；或卧未死已为人所寛。市中卖人肉，斤直钱百，犬肉直五百。茂贞储偫亦竭，以犬彘供御膳。上鬻御衣及小皇子衣于市以充用'),
'v263-y-902-p60': None,
'v263-y-902-p62': ('田頵率军急攻杭州，钱镠部将出战击退其军','田頵急攻杭州，仍具舟将自西陵渡江；钱镠遣其将盛造、朱郁拒破之。'),
'v263-y-902-p63': ('李茂勋遣使向朱全忠请降，凤翔山南州镇归王建、关中州镇归全忠','十二月，李茂勋遣使请降于朱全忠，更名周彝。于是茂贞山南州镇皆入王建，关中州镇皆入全忠，坐守孤城；'),
'v263-y-902-p64': None,
'v263-y-902-p65': ('张洪率三百步兵叛离越州投奔衢州，陈璋接纳；温州将丁章驱逐刺史并据城','越州客军指挥使张洪以徐绾之党自疑，帅步兵三百奔衢州，刺史陈璋纳之。温州将丁章逐刺史朱敖，敖奔福州。章据温州，田頵遣使招之，道出衢州；'),
'v263-y-902-p67': ('凤翔将李继昭出降朱全忠并恢复本姓符','李继昭谓全诲曰：「昔杨军容破杨守亮一族，今军容亦破继昭一族邪！」慢骂之，遂出降于全忠，复姓符，名道昭。'),
}
assert set(BATCH_258AC).issubset(byid)
BATCH_258AD = {
'v263-y-902-p68': ('卢光稠军攻取韶州并围攻潮州，刘隐反攻韶州而战败','是岁，虔州刺史卢光稠攻岭南，陷韶州，使其子延昌守之，进围潮州。清海刘隐发兵击走之，乘胜进攻韶州。隐弟陟以为延昌有虔州之援，未可遽取；隐不从，遂围韶州。会江涨，馈运不继，光稠自虔州引兵救之；其将谭全播伏精兵万人于山谷，以羸弱挑战，大破隐于城南，隐奔还。'),
'v263-y-903-p1': None,
'v263-y-903-p2': ('刘鄩率五百精兵夜入邢州，控制军城','适诸州者多事泄被擒，独行军司马刘鄩取兖州。时泰宁节度使葛从周悉将其兵屯邢州，鄩先遣人为贩油者入城，诇其虚实及兵所从入；丙午，鄩将精兵五百夜自水窦入，比明，军城悉定，市人皆不知。'),
'v263-y-903-p3': ('张居厚率壮士袭击华州，杀知州并攻城，后被崔胤击败捕获','是日，青州牙将张居厚帅壮士二百将小车至华州东城，知州事娄敬思疑其有异，剖视之；其徒大呼，杀敬思，攻西城。崔胤在华州，帅众拒之，不克，走至商州，追获之。'),
'v263-y-903-p4': ('朱全忠派朱友宁、葛从周率军东进讨伐王师范','迪不暇白全忠，亟请马步都指挥使朱友宁将兵万余人东巡兖、郓。友宁召葛从周于刑州，共攻师范。全忠闻变，亦分兵先归，使友宁并将之。'),
'v263-y-903-p5': ('昭宗派兵逮捕并处死韩全诲等宦官集团','上喜，即遣内养帅凤翔卒四十人收全诲等，斩之。'),
'v263-y-903-p6': None,
'v263-y-903-p7': ('朱全忠巡凤翔营寨时擒获凤翔将领李继钦','甲寅，凤翔始启城门。丙辰，全忠巡诸寨，至城北，有凤翔兵自北山一，全忠疑其逼己，遣兵击之，擒其将李继钦。'),
'v263-y-903-p10': ('昭宗出凤翔赴朱全忠军营，朱全忠遣军护送并焚撤营寨','甲子，车驾出凤翔，幸全忠营。全忠素服待罪；命客省使宣旨释罪，去三仗，止报平安，以公服入谢。全忠见上，顿首流涕；上命韩偓扶起之。上亦泣，曰：「宗庙社稷，赖卿再安；朕与宗族，赖卿再生。」亲解玉带以赐之。少休，即行。全忠单骑前导十余里，上辞之；全忠乃令朱友伦将兵扈从，自留部分后队，焚撤诸寨。'),
'v263-y-903-p12': ('朱全忠命兵驱逐并杀害宫中数百名宦官','是日，全忠以兵驱宦官第五可范等数百人于内侍省，尽杀之，冤号之声，彻于内外。其出使外方者，诏所在收捕诛之，止留黄衣幼弱者三十人以备洒扫。'),
'v263-y-903-p14': None,
'v263-y-903-p16': None,
'v263-y-903-p17': ('李克用出兵进攻晋州，闻昭宗东归后撤兵','河东监军张承业亦劝克用翻兵救凤翔，克用攻晋州，闻车驾东归，乃罢。'),
'v263-y-903-p18': ('李神福率淮南军攻取永兴，骆殷弃城逃走、方诏据城投降','以升州刺史李神福为淮南行军司马、鄂兵行营招讨使，舒州团练使刘存副之，将兵击杜洪。洪将骆殷戍永兴，弃城走，县民方诏据城降。'),
'v264-y-903-p6': None,
}
assert set(BATCH_258AD).issubset(byid)
BATCH_258AE = {
'v264-y-903-p8': ('朱全忠遣兵护送符道昭赴秦州，途中未能抵达而返回','全忠表符道昭同平章事，充天雄节度使，遣兵援送之秦州，不得至而还。'),
'v264-y-903-p9': None,
'v264-y-903-p12': ('朱全忠留万名步骑驻守京师并安插亲信控制宫禁','乙未，全忠奏留步骑万人于故两军，以朱友伦为左军宿卫都指挥使；又以汴将张廷范为宫苑使，王殷为皇城使，蒋玄晖充街使。于是全忠之党布列徧于禁卫及京辅。'),
'v264-y-903-p15': None,
'v264-y-903-p17': ('朱全忠遣军击退王师范援齐州军、断绝兖州援军并围攻青州','三月，戊午，朱全忠至大梁。王师范弟师鱼围齐州，朱友宁引兵击走之。师范遣兵益刘鄩军，友宁击取之。由是兖州援绝，葛从周引兵围之。友宁进攻青州；戊辰，全忠引四镇及魏博兵十万继之。'),
'v264-y-903-p18': None,
'v264-y-903-p21': ('淮南军援救王师范并出兵攻宿州，遭唐怀英击退','王师范求救于淮南，乙未，杨行密遣其将王茂章以步骑七千救之，又遣别将将兵数万攻宿州。全忠遣其将唐怀英救宿州，淮南兵遁去。'),
'v264-y-903-p23': None,
'v264-y-903-p24': ('王建发兵攻取秦、陇地区','王建出兵攻秦、陇，乘李茂贞之弱也；'),
'v264-y-903-p25': ('李嗣昭、李存审讨伐王敬晖叛乱，后者弃城逃走；又攻取振武并镇压契苾让','五月，丁未，李克用云州都将王敬晖杀刺史刘再立，叛降刘仁恭；克用遣李嗣昭、李存审将兵讨之。仁恭遣将以兵五万救敬，晖嗣昭退保乐安，敬晖举众弃城而去。先是，振武将契苾让逐戍将石善友，据城判；嗣昭等进攻之，让自燔死；复取振武城，杀吐谷浑叛者二千余人。'),
'v264-y-903-p27': ('李神福率军在君山击败荆南水军，焚毁战舰并击沉成汭','李神福闻其将至，自乘轻舟前觇之，谓诸将曰：「彼战舰虽多而不相属，易制也，当急击之！」壬子，神福遣其将秦裴、杨戎将众数千逆击汭于君山，大破之，因风纵火，焚其舰，士卒皆溃，汭赴水死，获其战舰二百艘。'),
'v264-y-903-p28': None,
'v264-y-903-p31': None,
'v264-y-903-p33': ('朱友宁攻陷博昌并屠城，继而攻取临淄、进围青州','朱友宁攻博昌，月余不拔；朱全忠怒，遣客将刘捍往督之。捍至，友宁驱民丁十余万，负木石，牵牛驴，诣城南筑土山，既成，并人畜木石排而筑之，冤号声闻数十里。俄而城陷，尽屠之。进拔临淄，抵青州城下，遣别将攻登、莱。'),
'v264-y-903-p34': ('王茂章率淮南军攻取密州并斩杀刺史刘康乂','淮南将王茂章会王师范弟莱州刺史师诲攻密州，拔之，斩其刺史刘康乂，以淮海都游弈使张训为刺史。'),
}
assert set(BATCH_258AE).issubset(byid)
BATCH_258AF = {
'v264-y-903-p35': ('朱友宁攻取登州并击败王师范、王茂章联军','六月，乙亥，汴兵拔登州。师范帅登、莱兵拒朱友宁于石楼，为两栅。丙子，夜，友宁击登州栅，栅中告急，师范趣茂章出战，茂章按兵不动。友宁破登州栅，进攻莱州栅。比明，茂章度其兵力已疲，乃与师范全兵出战，大破之。友宁旁自峻阜驰骑赴敌，马仆，青州将张土枭斩之，传首淮南。两镇兵逐北至米河，俘斩万计，魏博之兵殆尽。'),
'v264-y-903-p36': ('朱全忠率二十万军进攻青州，王师范出战败退，王茂章反击后撤','全忠闻友宁死，自将兵二十万昼夜兼行赴之，秋，七月，壬子，至临朐，命诸将攻青州。王师范出战，汴兵大破之。王茂章闭垒示怯，伺汴兵稍懈，毁栅而出，驱驰疾战，战酣退坐，召诸将饮酒，已而复战。全忠登高望见之，问降者，知为茂章，叹曰：「使吾得此人为将，天下不足平也！」至晡，汴兵乃退。茂章度众寡不敌，是夕，引军还。全忠遣曹州刺史杨师厚追之，及于辅唐。茂章命先锋指挥使李虔裕将五百骑为殿，虔裕殊死战，师厚擒而杀之。'),
'v264-y-903-p37': None,
'v264-y-903-p39': ('睦州刺史陈询叛乱并攻打兰溪，钱镠遣方永珍讨伐','睦州刺史陈询叛钱镠，举兵攻兰溪，镠遣指挥使方永珍击之。'),
'v264-y-903-p40': None,
'v264-y-903-p42': ('王宗本率军沿峡道进攻荆南','前汽州刺史王宗本言于王建，请出兵取荆南；建从之，以宗本为开道都指挥使，将兵下峡。'),
'v264-y-903-p43': ('田頵与安仁义举兵反叛杨行密，安仁义焚毁东塘战舰','及解释钱镠，頵尤恨之，阴有叛志。李神福言于行密曰：「頵必反，宜早图之。」行密曰：「頵有大功，反状未露，今杀之，诸将人人自危矣！」頵有良将曰唐儒，与頵谋议多不合，行密知之，擢儒为庐州刺史。頵以儒为贰于己，族之。儒曰：「吾死，田公亡无日矣！」頵遂与润州团练使安仁义同举兵，仁义悉焚东塘战舰。'),
'v264-y-903-p44': ('杨行密命李神福率水军沿江进军讨伐田頵','行密召李神福于鄂州，神福恐杜洪邀之，宣言奉命攻荆南，勒兵具舟楫；及暮，遂沿江东下，始告将士以讨田頵。'),
'v264-y-903-p45': ('安仁义袭击常州未克，杨行密增援徐温击败其军','己丑，安仁义袭常州，常州刺史李遇逆战，极口骂仁义，仁义曰：「彼敢辱我，必有备。」乃引去。壬辰，行密以茂章为润州行营招讨使，击仁义，不克，使徐温将兵会之。温易其服旗帜，皆如茂章兵，仁义不知益兵，复出战，温奋击，破之。'),
'v264-y-903-p46': ('朱全忠遣兵屯宿州，准备响应朱延寿、田頵谋反','行密夫人，朱延寿之姊也。行密狎侮延寿，延寿怨怒，阴与田頵通谋。頵遣前进士杜荀鹤至寿州，与延寿相结；又遣至大梁告朱全忠，全忠大喜，遣兵屯宿州以应之。'),
'v264-y-903-p47': ('杨师厚在临朐设伏击败王师范军及莱州援军，进逼青州','杨师厚屯临朐，声言将之密州，留辎重于临朐。九月，癸卯，王师范出兵攻临朐，师厚伏兵奋击，大破之，杀万余人，获师范弟师克。明日，莱州兵五千救青州，师厚邀击之，杀获殆尽，遂徙寨抵其城下。'),
'v264-y-903-p48': ('杨行密诱捕并处死朱延寿，随后处置其兄弟及亲兵','朱延寿谋颇泄，杨行密诈为目疾，对延寿使者多错乱所见，或触柱仆地。谓夫人曰：「吾不幸失明，诸子皆幼，军府事当悉以授三舅。」夫人屡以书报延寿；行密又自遣召之，阴令徐温为之备。延寿至广陵，行密迎及寝门，执而杀之；部兵惊扰，徐温谕之，皆听命，遂斩延寿兄弟，黜朱夫人。'),
'v264-y-903-p49': None,
'v264-y-903-p50': None,
'v264-y-903-p51': ('李神福率水军在吉阳矶、皖口击败田頵部将王坛、汪建并焚毁战舰','田頵袭升州，得李神福妻子，善遇之。神福自鄂州东下，頵遣使谓之曰：「公见机，与公分地而王；不然，妻子无遗！」神福曰：「吾以卒伍事吴王，今为上将，义不以妻子易其志。頵有老母，不顾而反，三纲且不知，乌足与言乎！」斩使者而进，士卒皆感励。頵遣其将王坛、汪建将水军逆战。丁未，神福至吉阳矶，与坛、建遇，坛、建执其子承鼎示之，神福命左右射之。神福谓诸将曰：「彼众我寡，当以奇取胜。」及暮，合战，神福佯败，引舟泝流而上；坛、建追之，神福复还，顺流击之。坛、建楼船大列火炬，神福令军中曰：「望火炬辄击之。」坛、建军皆灭火，旗帜交杂，神福因风纵火，焚其舰，坛、建大败，士卒焚溺死者甚众；戊申，又战于皖口，坛、建仅以身免。获徐绾，行密以槛车载之，遗钱镠；镠剖其心以祭高渭。'),
}
assert set(BATCH_258AF).issubset(byid)
BATCH_258AG = {
'v264-y-903-p52': None,
'v264-y-903-p55': ('王师范派遣使者向杨师厚请降，杨师厚接受并安排诸州守军','戊午，王师范遣副使李嗣业及弟师悦请降于杨师厚，曰：「师范非敢背德，韩全诲、李茂贞以朱书御札使之举兵，师范不敢违。」仍请以其弟师鲁为质。时朱全忠闻李茂贞、杨崇本将起兵逼京畿，恐其复劫天子西去，欲迎车驾都洛阳，乃受师范降，选诸将使守登、莱、淄、棣等州，即以师范权淄青留后。'),
'v264-y-903-p56': ('台蒙率军在广德、黄池击败田頵并围攻宣州','田頵闻台蒙将至，自将步骑逆战，留其将郭行悰以精兵二万及王坛、汪建水军屯芜湖，以拒李神福。觇者言：「蒙营寨褊小，纔容二千人。」頵易之，不召外□□蒙入頵境，番陈而进，军中笑其怯，蒙曰：「頵宿将多谋，不可不备。」冬，十月，戊辰，与頵遇于广德，蒙先以杨行密书徧赐頵将，皆下马拜受；蒙因其挫伏，纵兵击之，頵兵遂败。又战于黄池，兵交，蒙伪走；頵追之，遇伏，大败，奔还宣州城守，蒙引兵围之。頵亟召芜湖兵还，不得入。郭行悰、王坛、汪建及当涂、广德诸戍皆帅其众降。行密以台蒙已破田頵，命王茂章复引兵攻润州。'),
'v264-y-903-p57': ('王宗本接收夔州降军并平定夔、忠、万、施四州','初，夔州刺史侯矩从成汭救鄂州，汭死，矩奔还。会王宗本兵至，矩以州降之，宗本遂定夔、忠、万、施四州。'),
'v264-y-903-p58': None,
'v264-y-903-p59': ('葛从周围攻兖州，刘鄩坚守，援绝后出城投降','葛从周急攻兖州，刘鄩使从周母乘板舆登城，谓从周曰：「刘将军事我不异于汝，新妇辈皆安居，人各为其主，汝可察之。」从周歔欷而退，攻城为之缓。鄩悉简妇人及民之老疾不足当敌者出之，独与少壮者同辛苦，分衣食，坚守以扞敌；号令整肃，兵不为暴，民皆安堵。久之，外援既绝，节度副使王彦温踰城出降，城上卒多从之，不可遏。鄩遣人从容语彦温曰：「军士非素遗者，勿多与之俱。」又遣人徇于城上曰：「军士非素遣从副使而敢擅往者，族之！」士卒皆惶惑不敢出。敌人果疑彦温，斩之城下，由是众心益固。及王师范力屈，从周以祸福谕之，鄩曰：「受王公命守此城，一旦见王公失势，不俟其命而降，非所以事上也。」及师范使者至，丁丑，始出降。'),
'v264-y-903-p60': None,
'v264-y-903-p62': None,
'v264-y-903-p63': ('赵匡凝派兵攻取荆南，朗州守军弃城逃走','山南东道节度使赵匡凝遣兵袭荆南，朗人弃城走，匡凝表其弟匡明为荆南留后。'),
'v264-y-903-p64': ('朱全忠派骑兵驻扎河中防备凤翔等镇逼近京畿','凤翔、颁州屡出兵近京畿，朱全忠疑其复有劫迁之谋，十一月，发骑兵屯河中。'),
'v264-y-903-p65': ('台蒙在宣州城下击败田頵并攻克宣州','十一月，乙亥，田頵帅死士数百出战，台蒙阳退以示弱。頵兵谕濠而鬬，蒙急击之；頵不胜，还走城，桥陷坠马，斩之。其众犹战，以頵首示之，乃溃，蒙遂克宣州。'),
'v264-y-903-p68': None,
'v264-y-903-p69': None,
'v264-y-903-p70': ('朱全义派杨麟率兵围杀张浚于长水别墅','左仆射致仕张浚居长水，王师范之举兵，浚豫其谋。朱全忠将谋篡夺，恐浚扇动藩镇，讽张全义使图之。丙申，全义遣牙将杨麟将兵诈为劫盗，围其墅而杀之。'),
'v264-y-903-p72': None,
}
assert set(BATCH_258AG).issubset(byid)
BATCH_258AH = {
'v264-y-904-p0': ('朱友谅率兵包围崔胤宅第并杀死崔胤、郑元规等人','戊申，朱全忠密令宿卫都指挥使朱友谅以兵围崔胤第，杀胤及郑元规、陈班并胤所亲厚者数人。'),
'v264-y-904-p1': None,
'v264-y-904-p2': ('李继徽与李茂贞联合出兵逼近京畿','遂相与连兵侵逼京畿，复姓名为李继徽。'),
'v264-y-904-p3': ('朱全忠驻军河中并强迫昭宗及百官士民迁往洛阳','己酉，全忠引兵屯河中。丁巳，上御延喜楼，朱全忠遣牙将寇彦卿奉表，称邠、岐兵逼畿甸，请上迁都洛阳；及下楼，裴枢已得全忠移书，促百官东行。戊午，驱徙士民，号哭满路，骂曰：「贼臣崔胤召朱温来倾覆社稷，使我曹流离此！」老幼襁属，月余不绝。'),
'v264-y-904-p9': ('王建派兵迎接昭宗，行至兴平遭汴军阻挡而撤退','上遣间使以御札告难于王建，建以邛州刺史王宗祜为北路行营指挥使，将兵会凤翔兵迎车驾，至兴平，遇汴兵，不得进而还。'),
'v264-y-904-p10': None,
'v264-y-904-p13': ('李神福受命率军再次进攻杜洪','以淮南行军司马李神福为鄂岳招讨使，复将兵击杜洪。'),
'v264-y-904-p14': ('朱全忠派人收捕并处死反对迁都的朝臣及宫廷人员','至是，全忠令医官许昭远告医官使阎佑之、司天监王墀、内都知韦周、晋国夫人可证等谋害元帅，悉收杀之。'),
'v264-y-904-p15': ('朱全忠在迁都途中缢杀昭宗身边二百余名侍从并换置亲兵','癸卯，上憩于谷水。自崔胤之死，六军散亡俱尽，所余击球供奉、内园小儿共二百余人，从上而东。全忠犹忌之，为设食于幄，尽缢杀之。豫选二百余人大小相类者，衣其衣服，代之侍卫。上初不觉，累日乃寤。自是上之左右职掌使令皆全忠之人矣。'),
'v264-y-904-p16': None,
'v264-y-904-p17': None,
'v264-y-904-p21': None,
'v265-y-904-p3': ('李茂贞等结盟讨伐朱全忠，双方率军西进并在河中会师','六月，李茂贞、王建、李继徽传檄合兵以讨朱全忠；全忠以镇国节度使朱友裕为行营都统，将步骑击之；命保大节度使刘鄩弃鄜州，引兵屯同州，引兵屯同州。癸丑，全忠引兵自大梁西讨茂贞等；秋，七月，甲子，过东都入见；'),
'v265-y-904-p4': None,
'v265-y-904-p7': None,
}
assert set(BATCH_258AH).issubset(byid)
BATCH_258AI = {
'v265-y-904-p8': ('朱温部将史太率兵夜入宫中，杀死昭宗及裴贞一、李渐荣','八月，壬寅，帝在椒殿，玄晖选龙武牙官史太等百人夜叩宫门，言军前有急奏，欲面见帝。夫人裴贞一开门见兵，曰：「急奏何以兵为﹖」史太杀之。玄晖问：「至尊安在﹖」昭仪李渐荣临轩呼曰：「宁杀我曹，勿伤大家！」帝方醉，遽起，单衣绕柱走，史太追而弒之。渐荣以身蔽帝，太亦杀之。又欲杀何后，后求哀于玄晖，乃释之。'),
'v265-y-904-p9': None,
'v265-y-904-p10': None,
'v265-y-904-p11': ('李神福围攻鄂州未克，因病撤军返回广陵','淮南将李神福攻鄂州未下，会疾病，还广陵，'),
'v265-y-904-p13': ('朱全忠率军进驻永寿、骆谷一带后撤军东返','朱全忠引兵北屯永寿，南至骆谷，凤翔、邠宁兵竟不出。辛未，东还。'),
'v265-y-904-p15': ('朱全忠处死朱友恭、氏叔琮以回应弑君案并压下谤议','护驾军士有掠米于市者，甲午，全忠奏朱友恭氏叔琮不戢士卒，侵援市肆，友恭贬崖州司户，复姓名李彦威，叔琮贬白州司户，寻皆赐自尽。彦威临刑大呼曰：「卖我以塞天下之谤，如鬼神何！行事如此，望有后乎！」'),
'v265-y-904-p16': None,
'v265-y-904-p18': ('朱全忠率五万军渡淮进驻霍丘并分兵救援鄂州、迫使淮南军撤围','光州叛杨行密，降朱全忠，行密遣兵围之，与鄂州皆告急于全忠。十一月，戊辰，全忠自将兵五万自颍州济淮，军于霍丘，分兵救鄂州。淮南兵释光州之围还广陵，按兵不出战，全忠分命诸将大掠淮南以困之。'),
'v265-y-904-p19': ('钱镠部将叶让谋杀陈璋未遂，陈璋杀叶让后叛离两浙投奔杨行密','钱镠潜遣衢州罗城使叶让杀刺史陈璋，事泄；十二月，璋斩让而叛，降于杨行密。'),
'v265-y-904-p20': None,
'v265-y-904-p21': None,
'v265-y-904-p22': None,
'v265-y-905-p0': ('朱全忠派诸将进兵逼近寿州','春，正月，朱全忠遣诸将进兵逼寿州。'),
'v265-y-905-p1': ('王茂章率军围攻并攻陷润州，安仁义及其子被斩杀','茂章为地道入城，遂克之。仁义举族登楼，众不敢逼。'),
'v265-y-905-p2': ('两浙军围攻睦州，陶雅率援军击败其军并俘获顾全武、王球','两浙兵围陈诣于睦州，杨行密遣西南招讨使陶雅将兵救之；军中夜惊，士卒多踰垒亡去，左右及裨将韩球奔告之，雅安卧不应，须臾自定，亡者皆还。钱镠遣其从弟镒及指挥使顾全武、王球御之，为雅所败，虏镒及球以归。'),
}
assert set(BATCH_258AI).issubset(byid)
BATCH_258AJ = {
'v265-y-905-p4': None,
'v265-y-905-p8': ('刘存攻克鄂州并俘杀杜洪、曹延祚及汴军','朱全忠遣其将曹延祚将兵与杜洪共守鄂州，庚子，淮南将刘存攻拔之，执洪、祚及汴兵千余人送广陵，悉诛之。'),
'v265-y-905-p17': ('陶雅率衢州、睦州军攻打婺州，钱镠派弟镖领兵救援','淮南将陶雅会衢、睦兵攻婺州，钱镠使其弟镖将兵救之。'),
'v265-y-905-p20': None,
'v265-y-905-p30': ('天雄牙将李公佺发动叛乱，焚烧府舍、劫掠后逃往沧州','庚什夜，天雄牙将李公佺与牙军谋乱，罗绍威觉之；公佺焚府舍，剽掠，奔沧州。'),
'v265-y-905-p31': ('王建派王宗贺等率军进攻金州冯行袭','八月，王建遣前山南西道节度使垩宗贺等将兵击昭信节使冯行袭于金州。'),
'v265-y-905-p32': ('朱全忠派杨师厚率兵攻打赵匡凝，随后亲率大军增援','朱全忠以赵匡凝东与杨行密交通，西与王建结婚，乙未，遣武宁节度使杨师厚将兵击之；己亥，全忠以大军继之。'),
'v265-y-905-p33': ('卢约命弟弟卢佶攻陷温州，张惠逃往福州','处州刺史卢约使其弟佶攻陷温州，佶，巨乙翻。考异曰：新纪：「正月，约陷温州。」十国纪年在此月戊戌，今从之。〕张惠奔福州。'),
'v265-y-905-p36': ('杨师厚攻取汉北七州，击败赵匡凝军并攻陷襄州','杨师厚攻下唐、邓、复、郢、随、均、房七州，〔七州皆忠义军巡属。朱全忠军于汉北。九月，辛酉，命师厚作浮梁于阴谷口，襄州谷城县有阴城镇。按旧史，阴谷口在襄州西六十里。癸亥，引兵渡汉。浮梁成而渡。甲子，赵匡凝将兵二万陈于汉滨，〔陈，读曰阵。〕师厚与战，大破之，遂傅其城下。〔传，读如附。是夕，匡凝焚府城，帅其族及麾下士沿汉奔广陵。〔僖宗中和四年，赵德諲据襄州，传子匡凝，至是而亡。杨行密时据广陵，匡凝沿汉入江，顺流东下而奔归之。帅，读日率；下同。乙丑，师厚入襄阳；丙寅，全忠继至。'),
'v265-y-905-p37': None,
'v265-y-905-p39': ('赵匡明率两万军放弃荆南逃往成都，朱全忠军攻江陵并受降','丁卯，荆南节度使赵匡明帅众二万，弃城奔成都。戊辰，朱全忠以杨师厚为山南东道留后，引兵击江陵；至乐乡，荆南牙将王建武遣使迎降。'),
'v265-y-905-p40': ('王宗贺等攻取金州，冯行袭弃城逃走，守将全师朗投降','王宗贺等攻冯行袭，所向皆捷。丙子，行袭弃金州，奔均州；其将全师朗以城降。王建更师朗姓名曰王宗朗，补金州观察使，割渠、巴、开三州以隶之。'),
'v265-y-905-p42': ('陶雅、陈璋攻取婺州并俘获刺史沈夏，随后陈璋进攻暨阳受挫','淮南将陶雅、陈璋拔婺州，执刺史沈夏以归。杨行密以雅为江南都招讨使，歙、婺、衢、睦观察使；以璋为衢、婺副招讨使。璋攻暨阳，两浙将方习败之。习进攻婺州。'),
'v265-y-905-p44': None,
'v265-y-905-p45': None,
}
assert set(BATCH_258AJ).issubset(byid)
BATCH_258AK = {
'v265-y-905-p46': None,
'v265-y-905-p47': None,
'v265-y-905-p48': None,
'v265-y-905-p52': None,
'v265-y-905-p53': None,
'v265-y-905-p54': ('杨行密派兵抄袭朱全忠后军，斩首三千并夺取大量辎重','十一月，丙辰，朱全忠渡淮而北，迤再用抄其后军，斩首三千级，获辎重万计。全忠悔之，躁忿尤甚。丁卯，至大梁。'),
'v265-y-905-p60': None,
'v265-y-905-p64': None,
'v265-y-905-p65': None,
'v265-y-905-p66': ('杨渥即位后派李简率军袭击王茂章','杨渥之去宣州也，欲取其幄幕及亲兵以行，观察使王茂章不与，渥怒。既袭位，遣马步都指挥使李简等将兵袭之。'),
'v265-y-905-p67': ('湖南军进犯淮南，杨彪率军击退来犯者','湖南兵寇淮南，淮南雅内指挥使杨彪击却之。'),
'v265-y-906-p0': ('吐蕃七千余骑在宗高谷扎营，准备进攻嗢末并夺取凉州','春，正月，壬戌，灵武节度使韩逊奏吐蕃七千余骑营于宗高谷，将击嗢末及取凉州。'),
'v265-y-906-p1': ('李简率军突袭宣州，王茂章弃城逃往两浙；陶雅撤军，钱镠收复睦州','李简兵奄至宣州，王茂章度不能守，帅众奔两浙。亲兵上蔡刁彦能辞以母老，不从行，登城谕众曰：「王府命我招谕汝曹，大兵行至矣。」众由是定。陶雅畏茂章断其归路，引兵还歙州，钱镠复取睦州。'),
'v265-y-906-p3': ('罗绍威与朱全忠合谋消灭魏博牙军，联军突袭并尽杀牙军','初，田承嗣镇魏博，选募六州骁勇之士五千人为牙军，厚其给赐以自卫，为腹心；自是父子相继亲党胶固，岁久益骄横；小不如意，辄族旧帅而易之，自史宪诚以来皆立于其手。天雄节度使罗绍威心恶之，力不能制。朱全忠之围凤翔也，绍威遣军将杨利言密以情告全忠，欲借其兵以诛之。全忠以事方急，未暇如其请，阴许之。及李公佺作乱，绍威益惧，复遣牙将臧延范趣全忠。全忠乃发河南诸镇兵十万，遣其将李思安将之，会魏、镇兵屯深州乐城；声言击沧州，讨其纳李公佺也。会全忠女适绍威子廷规者卒，全忠遣客将马嗣勋实甲兵于橐中，选长直兵千人为担夫，帅之入魏，诈云会葬；全忠自以大军继其后，云赴行营；牙军皆不之疑。庚午，绍威潜遣人入库断弓弦、甲襻，是夕，绍威帅其奴客数百，与嗣勋合击牙军，牙军欲战而弓甲皆不可用，遂阖营殪之，凡八千家，婴孺无遗。诘旦，全忠引兵入城。'),
'v265-y-906-p6': ('王宗阮攻取归州并俘获守将韩从实','西川将王宗阮攻归州，获其将韩从实。'),
}
assert set(BATCH_258AK).issubset(byid)
BATCH_258AL = {
'v265-y-906-p7': ('两浙军攻取婺州并进攻衢州','陈璋闻陶雅归歙，自婺州退保衢州。两浙将方永珍等取婺州，进攻衢州。'),
'v265-y-906-p8': ('杨渥派陈知新率军攻取岳州并逐走刺史许德勋','杨渥遣先锋指挥使陈知新攻湖南。三月，乙丑，知新拔岳州，逐刺史许德勋，渥以知新为岳州刺史。'),
'v265-y-906-p11': ('史仁遇发动魏州牙军叛乱，占据高唐，多地响应；朱全忠军入魏并消灭叛军','会天雄牙将史仁遇作乱，聚众数万据高唐，自称留，后天雄巡内诸县多应之。全忠移军入城，遣使召行营兵还攻高唐，至历亭，魏兵在行营者作乱，与仁遇相应。元帅府左司马李周彝、右司马苻道昭击之，所杀殆半，进攻高唐，克之，城中兵民无少长皆死。擒史仁遇，锯杀之。'),
'v265-y-906-p12': ('李嗣昭率三千骑攻邢州七日未克，张筠设伏击败河东军','先是，仁遇求救于河东及沧州，李克用遣其将李嗣昭将三千骑攻邢州以救之。时邢州兵纔二百，团练使牛存节守之，嗣昭攻七日不克。全忠遣右长直都将张筠将数千骑助存节守城，筠伏兵于马岭，击嗣昭，败之，嗣昭遁去。'),
'v265-y-906-p13': ('刘守文军进攻贝、冀州并攻取蓨县；朱全忠派兵救冀州后沧州军撤退','义昌节度使刘守文遣兵万人攻贝州，又攻冀州，拔蓨县，进攻箪城。时镇州大将王钊攻魏州叛将李重霸于宗城。全忠遣归救冀州，沧州兵去。'),
'v265-y-906-p14': None,
'v265-y-906-p16': None,
'v265-y-906-p17': ('秦裴率军进攻江西钟匡时','杨渥以升州刺史秦裴为西南行营都招讨使，将兵击锺匡时于江西。'),
'v265-y-906-p18': None,
'v265-y-906-p19': None,
'v265-y-906-p20': ('朱全忠攻克相州并平定贝、博、澶、卫等地魏州叛军','秋，七月，朱全忠克相州。时魏之乱兵散据贝、博、澶、相、卫州，全忠分命诸将攻讨，至是悉平之，引兵南还。'),
'v265-y-906-p21': None,
'v265-y-906-p23': ('秦裴击破刘楚营寨、俘虏刘楚并围攻洪州，饶州刺史请降','秦裴至洪州，军于蓼洲。诸将请阻水立寨，裴不从；锺匡时果遣其将刘楚据之。诸将以咎裴，裴曰：匡时骁将独楚一人耳，若帅众守城，不可猝拔，吾故以要害诱致之耳。」未几，裴破寨，执楚，遂围洪州，饶州刺史唐宝请降。'),
'v265-y-906-p25': ('朱全忠率军自大梁出发，准备先攻沧州','朱全忠以幽、沧相首尾为魏患，欲先取沧州，甲辰，引兵发大梁。'),
'v265-y-906-p26': ('两浙军围攻衢州并最终攻取，周本设伏击败追击的浙军','两浙兵围衢州，衢州刺史陈璋告急于淮南，杨渥遣左厢马步都误候周本将兵迎璋。本至衢州，浙人解围，陈于城下，璋帅众归于本，两浙兵取衢州。吕师造曰：「浙人近我而不动，轻我也，请击之！」本曰：「吾受命迎陈使君，今至矣，何为复战！彼必有以待牛也。」遂引兵还。本为之殿，浙人蹑之，本中道设伏，大破之。'),
}
assert set(BATCH_258AL).issubset(byid)
BATCH_258AM = {
'v265-y-906-p27': None,
'v265-y-906-p29': ('杨崇本率凤翔等军攻夏州，刘知俊在坊州击败其军并俘获刺史','静难节度使杨崇本以凤翔、保塞、彰义、保义之兵攻夏州，匡国节度使刘知俊邀击坊州之兵，斩首三千余级，擒坊州刺史刘彦晖。'),
'v265-y-906-p30': ('刘仁恭大规模征发幽州境内男子组成十万军驻守瓦桥','刘仁恭救沧州，战屡败。乃下令境内：「男子十五以上，七十以下，悉自备兵粮诣行营，军发之后，有一人在闾里，刑无赦！」或谏曰：「今老弱悉行，妇人不能转饷，此令必行，滥刑者众矣。」乃命胜执兵者尽行，文其面曰「定霸都」，士人则文其腕或臂曰「一心事主」，于是境内士民，牦孺之外无不文者。得兵十万，军于瓦桥。'),
'v265-y-906-p31': ('朱全忠围困沧州，城中粮尽，百姓以土丸充食并互相掠食','时汴军筑垒围沧州，鸟鼠不能通。仁恭畏其强，不敢战。城中食尽，丸土而食，或互相掠啖。朱全忠使人说刘守文日：「援兵劫不相及，何不早降！」守文登城应之曰：「仆于幽州，父子也。梁王方以义服天下，若子叛父而来，将安用之！」全忠愧其辞直，为之缓攻。'),
'v265-y-906-p33': ('李克用派兵联合刘仁恭攻打潞州，以解沧州之围','刘仁恭求于河东，前后百余辈；李克用恨仁恭返覆，竟未之许，其子存勖谏曰：「今天下之势，归朱温者什七八，虽强大如魏博、镇、定莫不附之。自河以北，能为温患者独我与幽、沧耳，今幽、沧为温所困，我不与之并力拒之，非我之利也。夫为天下者不顾小怨，且彼尝困我而我救其急，以德怀之，乃一举而名实附也。此乃吾复振之时，不可失也。」克月以为然，与将佐谋召幽州兵与攻潞州，曰：「于彼可以解围，于我可以拓境。」乃许仁恭知，召其兵。仁恭遣都挥使李溥将兵二万诣晋阳，克用遣其将周德威、李嗣昭将兵与之共攻潞州。'),
'v265-y-906-p34': ('刘知俊、康怀贞率军在美原击败杨崇本五万军','夏州告急于朱全忠；戊戌，全忠遣刘佑俊及其将康怀英救之。杨崇本将六镇之兵五万，军于美原。佑俊等击之，崇本大败，归于邠州。'),
'v265-y-906-p35': ('雷彦威多次进犯荆南，朱全忠更换守将并派五千兵戍守后朗军撤退','武贞节度使雷彦威屡寇荆南，留后贺緕闭城自守；朱全忠以为怯，以颍州防御使高季昌代之，朱全忠以为怯，以颍州防御使高季昌代之，又遣驾前指挥使倪可福将兵五千戍荆南以备吴、蜀。朗兵引去。'),
'v265-y-906-p36': ('刘知俊、康怀贞攻取鄜、延等五州','十一月，刘佑俊、康怀贞乘胜攻鄜、延等五州，下之；'),
'v265-y-906-p38': None,
'v265-y-906-p39': ('朱全忠派李周彝率数万步骑兵从河阳出发救援潞州','朱全忠分步骑数万，遣行军司马李周彝将之，自河阳救潞州。'),
'v265-y-906-p40': None,
'v265-y-906-p41': ('李嗣昭围攻潞州，丁会率全军投降河东','初，昭宗凶讣至潞州，诏义节度使丁会帅将士缟素流涕久之。及李嗣昭攻潞州，会举军降于河东。李克用嗣昭为昭义留后。'),
'v265-y-906-p42': None,
'v265-y-906-p43': None,
'v265-y-906-p44': ('河东军进攻泽州未能攻克而撤退','河东兵进攻泽州，不克而退。'),
}
assert set(BATCH_258AM).issubset(byid)
BATCH_258AN = {
'v266-y-907-p2': ('淮南将领吕师周率部众投奔湖南，綦章放走其家属','黑云都指挥使吕师周与副指挥使綦章将兵屯上高，师周与湖南战，屡有功，渥忌之。师周惧，谋于綦章曰：「马公宽厚，吾欲逃死焉，可乎﹖」章曰：「兹事君自图之，吾舌可断，不敢泄！」师周遂奔湖南，章纵其孥使逸去。'),
'v266-y-907-p3': None,
'v266-y-907-p4': ('张颢、徐温借讨伐江西之名诛杀朱思勍等三将并发动兵谏夺权','渥之镇宣州也，命指挥使朱思勍、范思从陈璠将亲兵三千；及嗣位，召归广陵。颢、温使三将从秦裴击江西，因戍洪州，诬以谋叛，命别将陈佑往诛之。佑间道兼行，六日至洪州，微服怀短兵径入秦裴帐中．裴大惊，佑告之故，乃召思勍等饮酒，佑数思勍等罪，执而斩之。渥闻三将死，益忌颢、温，欲诛之。丙戍，渥晨视事，颢、温帅牙兵二百，露刃直入庭中，渥曰：「尔困欲杀我邪﹖」对曰：「非敢然也，欲诛王左右乱政者耳！」因子渥亲信十余人之罪，曳下，以铁檛击杀之谓之「兵谏」。诸将不与之同者，颢、温稍以法诛之，于是军政悉归二人，渥不能制。'),
'v266-y-907-p5': None,
'v266-y-907-p7': ('朱全忠命康怀贞调集京兆、同华军驻守晋州','河东兵犹屯长子，欲窥泽州。王命保平节度使康怀贞悉发京兆、同华之兵屯晋州以备之。'),
'v266-y-907-p9': ('朱全忠派李思安率军进攻幽州','三月，癸未，王以亳州刺史李思安为北路行军都统，将兵击幽州。'),
'v266-y-907-p11': ('钱镠派钱传褄、钱传瓘率军讨伐温州卢佶','镇海、镇东节度使吴王钱镠遣其子传褄、传瓘讨卢佶于温州。'),
'v266-y-907-p16': ('李思安率军进入幽州并败退，刘守光反攻控制幽州、囚捕并杀害刘仁恭亲信','李思安引兵入其境，所过焚荡无余。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山，城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。守光遂自称节度使，令部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。'),
'v266-y-907-p17': ('王思同、李承约率部众投奔河东，刘守奇随后逃往契丹、再奔河东','银胡踺都指挥使王思同帅部兵三千，山后八军巡检使李承约帅部兵二千奔河东；守光弟守奇奔契丹，未几，亦奔河东。'),
'v266-y-907-p19': ('钱传瓘间道突袭并攻取温州，擒杀卢佶；钱镠继而派军讨伐处州卢约','卢售闻钱传褄等将至，将水军拒之于青澳。钱传瓘曰：「售之精兵尽在于此，不可与战。」乃自安固舍舟，间道袭温州。戊午，温州溃，擒售斩之。吴王镠以都监使吴璋为温州制置使，命传褄等移兵讨卢约于处州。'),
'v266-y-907-p22': None,
'v266-y-907-p23': None,
'v266-y-907-p25': None,
'v266-y-907-p29': None,
'v266-y-907-p30': None,
}
assert set(BATCH_258AN).issubset(byid)
BATCH_258AO = {
'v266-y-907-p31': None,
'v266-y-907-p32': None,
'v266-y-907-p36': None,
'v266-y-907-p37': ('契丹阿保机率三十万骑军侵扰云州，与晋王约定当年冬季共同攻梁','是岁，阿保机帅众三十万寇云州，晋王与之连和，面会东城，约为兄弟，延之帐中，纵酒，渥手尽欢，约以今冬共击梁。或劝晋王：「因其来，可擒也，」王曰：「雠敌未灭而失信夷狄，自亡之道也。」阿保机留旨日乃去，晋王赠以金缯数万。阿保机留马三千匹，杂畜万计以酬之。阿保机归而背盟，更附于梁，晋王由是恨之。'),
'v266-y-907-p39': None,
'v266-y-907-p45': ('杨渥任命刘存、陈知新等率三万水军出征楚国','弘农王以鄂岳观察使刘存为西南面都招讨使，岳州刺史陈知新为岳州团练使，庐州观察使刘威为应援使，别将许玄应为监军，将水军三万以击楚。'),
'v266-y-907-p47': ('马殷派兵会同彭玕攻打洪州未能攻克','楚王殷遣兵会吉州刺史彭玕攻洪州，不克。'),
'v266-y-907-p48': ('康怀贞围攻潞州并筑壕堑切断城内外交通，晋王派军救援','康怀贞至潞州，晋昭义节度使李嗣昭、副使李嗣弼闭城拒守。怀贞昼夜攻之，半月不克，乃筑垒穿蚰蜒堑而守之，内外断绝。晋王以蕃、汉都指挥使周德威为行营都指挥使，帅马军都指挥使李嗣本、马步都虞候李存璋、先锋指挥使史建瑭、铁林都指挥使安元信、棋冲指挥使李嗣源、骑将安女全救潞州。'),
'v266-y-907-p49': ('朱全忠派范居实率军救援被围攻的泽州','晋兵攻泽州，帝遣左神勇军使范居实将兵救之。'),
'v266-y-907-p51': ('雷彦恭率武贞、楚军攻打江陵，高季昌截断粮道后击败之','武贞节度使雷彦恭会楚兵攻江陵，荆南节度使高季昌引兵屯公安，绝其粮道；彦恭败，楚兵亦走。'),
'v266-y-907-p54': ('雷彦恭攻取岳州','雷彦恭攻岳州，克。'),
'v266-y-907-p56': None,
'v266-y-907-p57': None,
'v266-y-907-p58': None,
'v266-y-907-p59': ('雷彦恭进攻涔阳、公安，被高季昌击败；朝廷命高季昌、马殷讨伐雷彦恭','九月，雷彦恭攻涔阳、公安，高季昌击败之。彦恭贪残类其父，专以焚掠为事，荆、湖间常被其患；又附于淮南。丙申，诏削彦恭官爵，命季昌与楚王殷讨之。'),
}
assert set(BATCH_258AO).issubset(byid)
BATCH_258AP = {
'v266-y-907-p63': ('高季昌、楚军围攻朗州，淮南援军被许德勋击败并俘杀泠业、李饶','冬，十月，高季昌遣其将倪可福会楚将秦彦晖攻朗州，雷彦恭遣使乞降于淮南，且告急，弘农王遣将泠业将水军屯平江，李饶将步骑屯浏阳以救之，楚王殷遣岳州刺史许德勋将兵拒之。泠业进屯朗口，德勋使善游者五十人，以木枝叶覆其首，持长刀浮江而下，夜犯其营，且举火，业军中惊扰。德勋以大军进击，大破之，追至鹿角镇，擒业；又破浏阳寨，擒李饶；掠上高、唐年而归。斩业、饶于长沙市。'),
'v266-y-907-p64': ('尹皓率兵攻取晋江潜岭寨','十一月，甲申，夹马指挥使尹皓攻晋江潜岭寨，拔之。'),
'v266-y-907-p65': ('刘守文为父亲被囚而起兵讨伐刘守光，双方交战','义昌节度使钊守文闻其弟守光幽其父，集将吏大哭曰：「不意吾家生此枭獍！吾生不如死，誓与诸君讨之！「乃发兵击守光，互有胜负。'),
'v266-y-907-p66': None,
'v266-y-907-p67': None,
'v266-y-907-p68': ('米志诚率淮南军渡淮攻取颍州外郭，刺史张实据内城拒守','淮南右都押牙米志诚等将兵渡淮袭颖州，克其外郭。刺史张实据子城拒守。'),
'v266-y-907-p69': ('李存璋围攻晋州，朝廷派河中、陕州军前往救援','晋王命李存璋攻晋州，以分上党兵势。十二月，壬戍，诏河中、陕州发兵救之。'),
'v266-y-907-p70': ('晋军袭击洺州','丁卯，晋兵寇洺州。'),
'v266-y-907-p71': ('淮南军攻打信州，刺史危仔倡向吴越求援','淮南兵攻信州，刺史危仔倡求救于吴越。'),
'v266-y-908-p0': None,
'v266-y-908-p3': None,
'v266-y-908-p4': None,
'v266-y-908-p5': None,
'v266-y-908-p6': ('钱镠派兵攻打淮南甘露镇以救援信州','吴越王镠遣兵攻淮南甘露镇，以救信州。'),
'v266-y-908-p9': None,
}
assert set(BATCH_258AP).issubset(byid)
BATCH_258AQ = {
'v266-y-908-p10': ('李存颢、李克宁图谋挟持晋王投梁，晋王伏兵擒杀二人','乃召李存璋、吴琪及假子李存敬、长直军使朱守殷，使阴为之备。壬戍，置酒会诸将于府舍，伏甲执克宁、存颢于座。晋王流涕数之曰：「数，所具翻。〕「儿向以军府让叔父，叔父不取。今事已定，柰何复为此谋，忍以吾母子遗仇雠乎！」克宁曰：「此皆谗人交构，夫复何言！」是日．杀克宁及存颢。'),
'v266-y-908-p12': ('蜀军攻入归州并俘获刺史张瑭','甲子，蜀兵入归州，执刺史张瑭。'),
'v266-y-908-p14': ('李思安围攻潞州未克，朱全忠增兵驻扎泽州并任命刘知俊统军','李思安等攻潞州，久不下，士卒疲弊，多逃亡。晋兵犹屯余吾寨，帝疑晋王克用诈死，欲召兵还，恐晋人蹑之，乃议自至泽州应接归师，且召匡国节度使刘知俊将兵趣泽州。三月，壬申朔，帝发大梁；丁丑，次泽州。辛巳，刘知俊至。壬午，以知俊为潞州行营招讨使。'),
'v266-y-908-p18': ('刘知俊率精兵击败晋军并请求留驻长子继续围攻上党','刘知俊将精兵万余人击晋军，斩获甚众，表请自留攻上党，车驾宜还京师。帝以关中空虚，虑岐人侵同华，命知俊休兵长子旬日，退屯晋州，俟五月归镇。'),
'v266-y-908-p19': ('蜀主命卫士扑杀图谋夺取兵权的王宗绾并处死其党羽','己亥，宗售入见，辞色悖慢；蜀主谕之，宗售不退，蜀主不堪其忿，命卫士扑杀之。贬其党御史中丞郑骞为维州司户，卫尉少卿李钢为汶川尉，皆赐死于路。'),
'v266-y-908-p20': None,
'v266-y-908-p22': ('晋王率周德威等军自晋阳出发，准备进攻梁军夹寨以解潞州之围','乃遣承业及判官王缄乞师于凤翔，又遣使赂契丹王阿保机求骑兵。岐王衰老，兵弱财竭，竟不能应。晋王大阅士卒，以前昭义节度使丁会为都招讨使。甲子，帅周德威等发晋阳。'),
'v266-y-908-p23': ('淮南军先后进攻石首、荆南，均被襄州军、高季昌击败','淮南遣兵寇石首，襄州兵败之于瀺港。又遣其将李厚将水军万五千趣荆南，高季昌逆战，败之于马头。'),
'v266-y-908-p24': ('晋王存勖率军突袭梁军夹寨，击溃敌军并杀招讨使符道昭','己巳，晋王军于黄碾，距上党四十五里。五月，辛未朔，晋王伏兵三垂冈下，诘旦大雾，进兵直抵夹寨。梁军无斥候，不意晋兵之至，将士尚未起，军中惊扰。晋王命周德威、李嗣源分兵为二道，德威攻西北隅，嗣源攻东北隅，填堑烧寨，鼓噪而入。梁兵大溃，南走，招讨使符道昭马倒，为晋人所杀；失亡将校士卒以万计，委弃资粮、器械山积。'),
'v266-y-908-p25': None,
'v266-y-908-p26': None,
'v266-y-908-p27': ('晋军进攻泽州，牛存节率梁军固守并击退来援的河东军','周德威、李存璋乖胜进趣泽州，刺史王班素失人心，众不为用。龙虎统军牛存节自西都将兵应接夹寨溃兵，至天井关，谓其众曰：「泽州要害地，不可失也；虽无昭旨，当救之。」众皆不欲，曰：「晋人胜气方锐，且众寡不敌。」存节曰：「见危不救，非义也；畏敌强而避之，非勇也。」遂举策引众而前。至泽州，城中人已纵火諠噪，欲应晋王，班闭牙城自守，存节至，乃定。晋兵寻至，缘城穿地道攻之，存节昼夜拒战，凡旬有三日；刘知俊自晋州引兵救之，德威焚攻具，退保高平。'),
'v266-y-908-p28': None,
'v266-y-908-p31': None,
'v266-y-908-p33': None,
}
assert set(BATCH_258AQ).issubset(byid)
BATCH_258AR = {
'v266-y-908-p34': ('楚军进攻鄂州，被淮南守将秦裴击败','乙亥，楚兵寇鄂州，淮南所署知州秦裴击破之。'),
'v266-y-908-p35': ('张颢等弑杀淮南王杨渥','张颢、右牙指挥使徐温专制军政，弘农威王心不能，欲去之而未能。二人不自安，共谋弒王，分其地以臣于梁。戊寅，颢遣其党纪祥等弒王于寝室，诈云暴薨。'),
'v266-y-908-p36': None,
'v266-y-908-p37': ('张颢派刺客夜袭严可求未遂','颢知可求阴附温，夜，遣盗刺之；可求知不免，请为书辞府主。盗执刀临之，可求操笔无惧色；盗能辨字，见其辞恉忠壮，曰：「公长者，吾不忍杀。」掠其财以复命，曰：「捕之不获。」颢怒曰：「吾欲得可求首，何用财为！」'),
'v266-y-908-p38': ('钟泰章率三十壮士夜入牙堂，刺杀张颢并诛其亲信','温与可求谋诛颢，可求曰：「非锺泰章不可。」泰章者，合肥人，时为左监门卫将军。〔考异曰：吴纪作「锺章」。十国纪年作「锺奉章」，今从之。〔温使亲将〔【章：十二行本「将」下有「彭城」二字；乙十一行本同；孔本同；张校同。】〕翟虔告之。〔翟，直格翻，姓也。〕泰章闻之喜，密结壮士三十人，夜，刺血相饮为誓；〔刺，七亦翻。饮，于禁翻。〕丁亥旦，直入斩颢于牙堂，〔牙堂，左右牙指挥使治事之所。〕并其亲近。温始暴颢弒君之罪，〔暴者，发露其罪，音如字。〕轘纪祥等于市。'),
'v266-y-908-p39': None,
'v266-y-908-p41': None,
'v266-y-908-p42': ('秦彦晖率楚军夜袭攻陷朗州，雷彦恭逃往广陵','雷彦恭引沅江环朗州以自守，秦彦晖顿兵月余不战，彦恭守备稍懈；彦晖使裨将曹德昌帅壮士夜入自水宝，内外举火相应，城中惊乱，彦晖鼓噪坏门而入，彦恭轻舟奔广陵。彦晖虏其弟彦雄，送于大梁。淮南以彦恭为节度副使。先是，沣州刺史向緕与彦恭相表裹，至是亦降于楚，楚始得沣、朗二州。'),
'v266-y-908-p43': ('蜀军会同岐军五万进攻雍州，朱梁派刘知俊统军迎击','蜀主遣将将兵会岐兵五万攻雍州，晋张承业亦将兵应之。六月，壬寅，以刘知俊为西路行营都招讨使以拒之。'),
'v266-y-908-p44': ('朱全忠命人诱捕并处死王师范及其家族二百人','金吾上将军王师范家于洛阳，朱友宁之妻泣诉于帝曰：「陛下化家为国，宗族皆蒙荣宠。妾夫独不幸，因不师范叛逆，死于战场；今仇雠犹在，妾诚痛之！」帝曰：「朕几忘此贼！」己酉，遣使就洛阳族之。使者先凿坑于第侧，乃宣敕告之；师范盛陈宴具，与宗族列坐，谓使者曰：「死者人所不免，况有罪乎！予不欲使积尸长幼无予。」酒既行，命自幼及长，引于坑中戮之，死者凡二百人。'),
'v266-y-908-p45': ('刘知俊、王重师在幕谷击败岐军，晋、蜀军撤退','丙辰，刘知俊及佑国节度使王重师大破岐兵于幕谷，晋、蜀兵皆引归。'),
'v266-y-908-p47': None,
'v267-y-908-p3': ('周德威、李嗣昭攻打晋州，朱全忠亲率军救援后河东军撤退','晋周德威、李嗣昭将兵三万出阴地关，攻晋州，刺史徐怀玉拒守；帝自将救之，丁丑，发大梁，乙酉，至陕州。戊子，岐王所署延州节度使胡敬璋寇上平关，刘知俊击破之。周德威等闻帝将至，乙未，退保隰州。'),
'v267-y-908-p4': ('高季昌截断楚军朝贡水路，许德勋击退其军；马殷军攻取岭南六州','荆南节度使高季昌遣兵屯汉口，绝楚朝贡之路；楚王殷遣其将许德勋将水军击之，至沙头，季昌惧而请和。殷又遣步军都指挥使吕师周将兵击岭南，与清海节度使刘隐十余战，取昭、贺、梧、蒙、龚、富六州。'),
}
assert set(BATCH_258AR).issubset(byid)
BATCH_258AS = {
'v266-y-908-p48': None,
'v267-y-908-p11': ('寇彦卿率二千兵袭霍丘被朱景击败，后攻庐、寿二州未克而撤回','帝从吴越王镠之请，以亳州团练使寇彦卿为东南面行营都指挥使，击淮南。十一月，彦卿帅众二千袭霍丘，为土豪朱景所败；又攻庐、寿二州，皆不胜。淮南遣滁州刺史史俨拒之，彦卿引归。'),
'v267-y-908-p13': ('刘守文率沧、德军攻打幽州，刘守光获晋军援助后在卢台、玉田两次击败之','刘守文举沧德兵攻幽州，刘守光求救于晋，晋王遣兵五千助之。丁亥，守文兵至卢台军，为守光所败；又战玉田，亦败。守文乃还。'),
'v267-y-908-p16': None,
'v267-y-909-p3': ('李延实杀死延州刺史刘万子并占据延州，高万兴、万金等率部众投降刘知俊','保塞节度使刘万子暴虐，失众心，且谋贰于梁，李继徽使延州牙将李延实图之。延实因万子葬胡敬璋，攻而杀之，遂据延州。马军都指挥使河西高万兴与其弟万金闻变，以其众数千人诣刘知俊降。岐王置翟州于鄜城，其守将亦降。'),
'v267-y-909-p4': None,
'v267-y-909-p5': ('朱全忠派军与高万兴部会合，准备攻取丹州、延州','庚辰，帝至河中，发步骑会高万兴兵取丹、延。'),
'v267-y-909-p8': None,
'v267-y-909-p9': ('刘知俊移军进攻延州并派兵围攻坊州','夏，四月，丙申朔，刘知俊移军攻延州，李延实婴城自守；知俊遣白水镇使刘儒分兵围坊州。'),
'v267-y-909-p12': ('淮南军攻围苏州，吴越派钱镖、杜建徽率军救援','淮南兵围苏州，推洞屋攻城，吴越将临海孙琰置轮于竿首，垂焴投锥以揭之，攻者尽露，禄至则张网以拒之，淮南人不能克。吴越王镠遣牙内指挥使钱镖、行军副使杜建徽等将兵救之。'),
'v267-y-909-p13': None,
'v267-y-909-p14': None,
'v267-y-909-p15': None,
'v267-y-909-p19': None,
'v267-y-909-p22': ('刘守文率沧、德军在鸡苏被刘守光击败并被俘；守光继而进攻沧州','刘守文频年攻刘守光不克，乃大发兵，以重赂招契丹，吐谷浑之众，合四万屯蓟州。守光逆战于鸡苏，为守文所败。守文单马立于陈前，泣谓其众曰：「勿杀吾弟。」守光将元行钦识之，直前擒之，沧德兵皆溃。守光囚之别室，栫以藂棘，乘胜进攻沧州。沧州节度判官吕兖、孙鹤推守文子延祚为帅，乘城拒守。'),
}
assert set(BATCH_258AS).issubset(byid)
BATCH_258AT = {
'v267-y-909-p23': ('刘知俊率同州附岐，袭取华州并控制潼关，且诱捕杀死刘捍','六月，乙未朔，知俊奏「为军民所留」，遂以同州附于岐。执监军及将佐之不从者，皆械送于岐。遣兵袭华州，逐刺史蔡敬思，以兵守潼关。潜遣人以重利啖长安诸将，执刘捍，送于岐，杀之。'),
'v267-y-909-p25': ('朱全忠任杨师厚为西路招讨使，率刘鄩等出兵讨伐刘知俊','庚戍，诏削知俊官爵，以山南东道节度使杨师厚为西路行营招讨使，帅侍卫马步军都指挥使刘鄩等讨之。'),
'v267-y-909-p26': ('丹州马军发动叛乱并杀死刺史宋知诲','丹州马军都头王行思等作乱，刺史宋知诲逃归。'),
'v267-y-909-p28': ('刘鄩部攻取潼关并俘获刘知浣','刘鄩至潼关东，获刘知俊伏路兵蔺如海等三十人，释之使为前导。刘知浣迷失道，盘桓数日，乃至关下，关吏纳之。如海等继至，关吏不知其已被擒，亦纳之。鄩兵乘门开直进，遂克潼关，追及知浣，擒之。'),
'v267-y-909-p29': ('刘知俊家族逃往岐州，杨师厚军夺回长安并攻克华州','帝遣刘知俊侄嗣业持诏诣同州招谕知俊；知俊欲轻骑诣行在谢罪，弟知偃止之。杨师厚等至华州，知俊将聂赏开门降。知俊闻潼关不守，官军继至，苍黄失图，乙卯，举族奔岐。杨师厚至长安，岐兵已据城，师厚以奇兵并南山急趋，自西门入，遂克之。庚申，以刘鄩权佑国留后。岐王厚礼刘知俊，以为中书令。'),
'v267-y-909-p30': None,
'v267-y-909-p31': ('危全讽率抚、信、袁、吉军进攻洪州，楚军围攻高安援助','抚州刺史危全讽自称镇南节度使，帅抚、信、袁、吉之兵号十万攻洪州。淮南守兵纔千人，将吏皆惧，节度使刘威密遣使告急于广陵，日召僚佐宴饮。全讽闻之，屯象牙潭，不敢进，请兵于楚；楚王殷遣指挥使苑玫会袁州刺史彭彦章围高安以助全讽。'),
'v267-y-909-p32': None,
'v267-y-909-p34': None,
'v267-y-909-p36': None,
'v267-y-909-p37': ('河东军进犯晋州并沿途掠夺至尧祠','河东兵寇晋州，抄掠至尧祠而去。'),
'v267-y-909-p39': ('襄州兵变杀死节度留后王班，叛军立李洪并归附蜀；房州刺史杨虔随后叛蜀','初，帝召山南东道节度使杨师厚，欲使督诸将攻潞州，以前兖海留后王班为留后，镇襄州。师厚屡为班言牙兵王求等凶悍，宜备之，班自恃左右有壮士，不以为意，每众辱之。戊寅，㻙求戍西境，是夕，作乱，杀班，推都指挥使雍丘刘閗为留后；閗伪从之，明日，与指挥使王延顺逃诣帝所。乱兵奉平淮指挥使李洪为留后，附于蜀。未几，房州刺史杨虔亦叛附于蜀。'),
'v267-y-909-p40': ('周本在象牙潭设伏大破危全讽十万军，擒获全讽及五千将士','危全讽在象牙潭，营栅临溪，亘数十里。庚辰，周本隔溪布陈，先使羸兵尝敌；全讽兵涉溪追之，本乘其半济，纵兵击之；全讽兵大溃，自相蹂藉，溺水死者甚众，本分兵断其归路，擒全讽及将士五千人。乘胜克袁州，执刺史彭彦章，进攻吉州。歙州刺史陶雅使其子敬昭及都指挥使徐章将兵袭饶、信，信州刺史危仔倡请降，饶州刺史唐宝弃城走。行营都指挥使米志诚、都尉吕师造等败苑玟于上高。吉州刺史彭玕帅众数千人奔楚，楚王殷表玕为郴州刺史，为子希范娶其女。淮南以左先锋指挥使张景思知信州，遣行营都虞侯骨言将兵五千送之。危仔倡闻兵至，奔吴越，吴越王镠以仔倡为淮南节度副使，更其姓曰元氏。危全讽至广陵，弘农王以其尝有德于武忠王，释之，资给甚厚。八月，虔州刺史卢光稠以州附于淮南。于是江西之地尽入于杨氏。光稠亦遣使附于梁。'),
'v267-y-909-p42': None,
'v267-y-909-p43': None,
}
assert set(BATCH_258AT).issubset(byid)
BATCH_258AU = {
'v267-y-909-p45': ('晋军攻围晋州，梁军救援击退周德威并解围','岐王欲遣刘知俊将兵攻灵、夏，且约晋王使攻晋、绛。晋王引兵南下，先遣周德威等将兵出阴地关攻晋州，刺史边继威悉力固守。晋兵穿地道，陷城二十余步，城中血战拒之，一夕城复成。诏杨师厚将兵救晋州，周德威以骑扼蒙坑之险，师厚击破之，进抵晋州，晋兵解围遁去。'),
'v267-y-909-p46': ('李洪进犯荆南及梁军出兵平定襄州叛乱','李洪寇荆南，高季昌遣其将倪可福击败之。诏马步都指挥使陈晖将兵会荆南兵讨洪。'),
'v267-y-909-p48': ('陈晖击败李洪叛军，攻取襄州并处决李洪、杨虔','陈晖军至襄州，李洪逆战，大败，王求死。九月，丁酉，拔其城，斩叛兵千人，执李洪、杨虔等送洛阳，斩之。'),
'v267-y-909-p49': None,
'v267-y-909-p50': None,
'v267-y-909-p54': ('高澧诱杀湖州民兵并引发兵变，继而叛附淮南焚掠镇戍','时澧纠民为兵，有言其咨怨者，澧悉集民兵于开元寺，绐云犒享，入则杀之；死者踰半，在外者觉之，纵火作乱。澧闭城大索，凡杀三千人。吴越王镠欲诛之，戊辰，澧以州叛附于淮南，举兵焚义和临平镇，镠命指挥使钱镖讨之。'),
'v267-y-909-p56': None,
'v267-y-909-p57': ('岐梁围绕灵州及邠宁连续交战，康怀贞等援军遭伏大败','岐王欲取灵州以处刘知俊，且以为牧马之地，使知俊自将兵攻之。朔方节度使韩逊告急；诏镇国节度使康怀贞、感化节度使寇彦卿将兵攻邠宁以救之。怀贞等所向皆捷，克宁、衍二州，拔庆州南城，刺史李彦广出降。游兵侵掠至泾州之境，刘知俊闻之，十二月，己丑，解灵州围，引兵还。帝急召贞等还，遣兵迎援于三原青谷；怀贞等还，至三水，知俊遣兵据险邀之，左龙骧军使寿张王彦章力战，怀贞等乃得过。怀贞与裨将李德遇、许从实、王审权分道而行，皆与援兵不相值，至升平，刘知俊伏兵山口，怀贞大败，仅以身免，德遇等军皆没。岐王以知俊为彰义节度使，镇泾州。'),
'v267-y-909-p58': None,
'v267-y-909-p60': ('沧州围城断粮，城中百姓食泥并发生人相食','刘守光围沧州久不下，执刘守文至城下示之，犹固守。城中食尽，民食菫泥，军士食人，驴马相噉鬃尾。吕兖选男女羸弱者，饲以曲裇而烹之，以给军食，谓之宰杀务。'),
'v267-y-910-p5': ('吴军援救湖州未能入城，高澧率五千部众逃往吴国','高澧求救于吴，吴常州刺史李简等将兵应之，湖州将盛师友、沈行思闭城不内；澧帅麾下五千人奔吴。'),
'v267-y-910-p9': None,
'v267-y-910-p10': None,
'v267-y-910-p11': None,
'v267-y-910-p15': None,
}
assert set(BATCH_258AU).issubset(byid)
BATCH_258AV = {
'v267-y-910-p16': ('楚军进攻荆南，被高季昌击败并斩首五千','殷遣将侵荆南，军于油口；高季昌击破之，斩首五千级，逐北至白田而还。'),
'v267-y-910-p17': ('吴军围攻赤石，楚军救援并俘获吴水军将领敖骈','吴水军指挥使敖骈围吉州刺史彭玕弟瑊于赤石，楚兵救瑊，虏骈以归。'),
'v267-y-910-p20': ('晋与岐、邠军围攻夏州李仁福','晋王遣振武节度使周德威将兵会之，合五万众围夏州，仁福婴城拒守。'),
'v267-y-910-p23': ('梁军出兵救援夏州并截击围城的晋、岐军','辛未，以镇国节度使杨师厚为西路行营招讨使，会感化节度使康怀贞将兵三万屯三原。帝忧晋兵出泽州逼怀州，既而闻其在绥、银碛中，曰：「无足虑也。」甲申，遣夹马指挥使李遇、刘绾自鄜、延趋银、夏，邀其归路。'),
'v267-y-910-p26': None,
'v267-y-910-p27': ('梁军进驻泽州，准备谋取上党','冬，十月，遣镇国节度使杨师厚、相州刺史李思安将兵屯泽州以图上党。'),
'v267-y-910-p28': None,
'v267-y-910-p29': ('梁军向上党进发后转屯魏州','以宁国节度使、同平章事王景仁充北面行营都指挥招讨使，潞州副招讨使韩勍副之，以李思安为先锋将，趣上党。寻遣景仁等屯魏州，杨师厚还陕。'),
'v267-y-910-p31': None,
'v267-y-910-p33': ('梁军以假称助防为名进驻深、冀，杀赵军戍卒','会燕王守光发兵屯涞水，欲侵定州，上遣供奉官杜廷隐、丁延徽监魏博兵三千分屯深、冀，声言恐燕兵南寇，助赵守御；又云分兵就食。赵将石公立戍深州，白赵王镕，请拒之。镕遽命开门，移公立于外以避之。'),
'v267-y-910-p34': None,
'v267-y-910-p35': ('晋军出井陉增援赵州','乃发兵，遣周德威将之，出井陉，屯赵州。'),
'v267-y-910-p36': None,
'v267-y-910-p37': ('梁军渡河进驻邢、洺，准备与晋赵联军交战','十二月，己未，上闻赵与晋合，晋兵已屯赵州，乃命王景仁等将兵击之。庚申，景仁等自河阳渡河，会罗周翰兵，合四万，军于邢、洺。'),
'v267-y-910-p38': ('吴国增兵新淦，谋取虔州','吴淮南节度判官严可求请置制置使于新淦县，遣兵戍之，以图虔州。每更代，辄潜益其兵，虔人不之觉也。'),
'v267-y-910-p41': None,
'v267-y-910-p43': None,
'v267-y-910-p44': None,
}
assert set(BATCH_258AV).issubset(byid)
BATCH_258AW = {
'v267-y-910-p45': None,
'v267-y-910-p46': ('楚军出兵讨伐侵扰边境的辰州、溆州蛮部','至是，邺寇湘乡，金盛寇武冈。楚王殷遣昭州刺史吕师周将衡山兵五千讨之。'),
'v267-y-910-p47': ('庞巨昭、刘昌鲁向楚国归降，楚军进驻容州并接迎高州军民','是岁，致书请自归于楚，楚王殷大喜，遣横州刺史姚彦章将兵迎之。彦章至容州，裨将莫彦昭说巨昭曰：「湖南兵远来疲乏，宜撤储偫，弃城，潜于山谷以待之。彼必入城，我以全军掩之，彼外无继援，可擒也。」巨昭曰：「马氏方兴，今虽胜之，后将何如！不若具牛酒迎之。」彦昭不从，巨昭杀之，举州迎降。彦章进至高州，以兵援送巨昭、昌鲁之族及士卒千余人归长沙。'),
'v267-y-911-p2': ('晋军在柏乡大破梁军，斩首二万并追击至邢州','时魏、滑之兵陈于东，宋、汴之兵陈于西。至晡，梁军未食，士无鬬志，景仁等引兵稍却，周德威疾呼曰：「梁兵走矣！」晋兵大噪争进，魏、滑兵先退，李嗣源帅众噪于西陈之前曰：「东陈已走，尔何久留！」梁兵互相惊怖，遂大溃。李存璋引步兵乘之，呼曰：「梁人亦吾人也，父兄子弟饷军者勿杀。」于是战士悉解甲投兵而弃之，嚣声动天地。赵人以深、冀之憾，不顾剽掠，但奋白刃追之，梁之龙骧、神捷精兵殆尽，自野河至柏乡，僵尸蔽地。王景仁、韩勍、李思安以数十骑走。晋兵夜至柏乡，梁兵已去，弃粮食、资财、器械不可胜计。凡斩首二万级。李嗣源等追奔至邢州，河朔大震。'),
'v267-y-911-p3': ('梁军败退后屠杀深、冀百姓并掳掠二州丁壮','杜廷隐等闻梁兵败，弃深、冀而去，悉驱二州丁壮为奴婢，老弱者坑之，城中存者坏垣而已。'),
'v267-y-911-p4': ('晋军攻邢、魏等地，梁军增援并攻取河北诸州','己亥，晋王遣周德威、史建瑭将三千骑趣澶、魏，张承业、李存璋以步兵攻邢州，自以大军继之，移檄河北州县，谕以利害。'),
'v267-y-911-p7': ('晋军围攻魏州未克，梁援军入城并迫使晋军退渡黄河','二月，己未，晋王至魏州，攻之，不克。上以罗周翰年少，且忌其旧将佐，庚申，以户部尚书李振为天雄节度副使，命杜廷隐将兵千人卫之，自杨刘济河，间道夜入魏州，助周翰城守。癸亥，晋王观河于黎阳，梁兵万余将渡河，闻晋王至，皆弃舟而去。'),
'v267-y-911-p8': ('蔡州军士作乱焚掠，王存俨诛平叛乱并接管州务','蔡州右指挥使刘行琮作乱，纵兵焚掠，将奔淮南；顺化指挥使王存俨诛行琮，抚遏其众，自领州事，以众情驰奏。'),
'v267-y-911-p9': ('晋军连续攻取贝、博、澶等州并进逼卫州，梁帝率军防备','乙丑，周德威自临清攻贝州，拔夏津、高唐；攻博州，拔东武、朝城。攻澶州，刺史张可瑧弃城走，帝斩之。德威进攻黎阳，拔临河、淇门；逼卫州，掠新乡、共城。庚午，帝亲帅军屯白司马阪以备之。'),
'v267-y-911-p10': ('杨师厚率梁军解邢、魏之围并追击晋军','会杨师厚自磁、相引兵救邢、魏，壬申，晋解围去；师厚追之，逾漳水而还，邢州围亦解。师厚留屯魏州。'),
'v267-y-911-p11': ('赵王镕犒劳晋军并派三十七都兵随晋王征讨','自是遣其养子德明将三十七都常从晋王征讨。'),
'v268-y-911-p3': ('温韬率岐军寇长安，梁军在车度击败温韬','使帅邠、岐兵寇长安。诏感化节度使康怀贞、忠武节度使牛存节以同华、河中兵讨之。己酉，怀贞等奏击韬于车度，走之。'),
'v268-y-911-p4': ('岐军进犯兴元，被蜀军击退','夏，四月，乙卯朔，岐兵寇蜀兴元，唐道袭击却之。'),
'v268-y-911-p8': None,
'v268-y-911-p9': None,
'v268-y-911-p12': None,
'v268-y-911-p13': None,
'v268-y-911-p14': None,
'v268-y-911-p15': None,
'v268-y-911-p17': None,
}
assert set(BATCH_258AW).issubset(byid)
BATCH_258AX = {
'v268-y-911-p19': ('岐军击败蜀军并围困安远军，蜀军援兵反击取胜','岐王使刘知俊、李继崇将兵击蜀，乙亥，王宗侃、王宗贺、唐道袭、王宗绍与之战于青泥岭，蜀兵大败，马步使王宗浩奔兴州，溺死于江，道袭奔兴元。先是，步军都指挥使王宗绾城西县，号安远军，宗侃、宗贺等收散兵走保之，知俊、继崇追围之。众议欲弃兴元，道袭曰：「无兴元则无安远，利州遂为敌境矣。吾必以死守之。」蜀主以昌王宗鐬为应援招讨使，定戎团练使王宗播为四招讨马步都指挥使，将兵救安远军，壁于廉、让之间，与唐道袭合击岐兵，大破之于明珠曲。明日又战于凫口，斩其成州刺史李彦琛。'),
'v268-y-911-p20': None,
'v268-y-911-p23': None,
'v268-y-911-p24': None,
'v268-y-911-p25': None,
'v268-y-911-p27': ('保塞军出兵攻取盐州，刺史高行存投降','庚寅，保塞节度使高万兴奏遣都指挥使高万金将兵攻盐州，刺史高行存降。'),
'v268-y-911-p29': None,
'v268-y-911-p30': None,
'v268-y-911-p32': ('黎球发动兵变杀卢延昌并控制虔州；刘岩攻占韶州','镇南留后卢延昌游猎无度，百胜军指挥使黎球杀之，自立；将杀谭全播，全播称疾请老，乃免。丙辰，以球为虔州防御使。未几，球卒，牙将李彦图代知州事，全播愈称疾笃。刘岩闻全播病，发兵攻韶州，破之，刺史瘳爽奔楚，楚王殷表为永州刺史。'),
'v268-y-911-p35': None,
'v268-y-911-p36': ('晋军出兵三万攻燕，声称救援易定','甲子，晋王遣蕃汉马步总管周德威将兵三万攻燕，以救易定。'),
'v268-y-912-p0': ('晋赵义武联军进攻燕国，攻克祁沟关并迫使涿州投降','春，正月，德威东出飞狐，与赵王将王德明、义武将程岩会于易水。丙戌，三镇兵进攻燕祁沟关，下之；戊子，围涿州。刺史刘知温城守，刘守奇之客刘去非大呼于城下，谓知温曰：「河东小刘郎来为父讨贼，何豫汝事而坚守邪﹖」守奇免冑劳之，知温拜于城上，遂降。'),
'v268-y-912-p1': None,
'v268-y-912-p2': None,
'v268-y-912-p3': None,
'v268-y-912-p5': ('梁军围攻枣强及蓨县','乙亥，帝至魏州，命都招讨使宣义节度使杨师厚、副使．前河阳节度使李周彝围枣强，招讨应接使．平卢节度使贺德伦、副使．天平留后袁象先围蓨县。'),
'v268-y-912-p8': None,
'v268-y-912-p9': None,
'v268-y-912-p10': None,
'v268-y-912-p11': ('义昌军兵变杀刘继威，张万进夺取军府并请降','义昌节度使刘继威年少，淫虐类其父，淫于都指挥使张万进家，万进怒，杀之。诘旦，召大将周知裕，告其故。万进自称留后，以知裕为左都押牙。庚子，遣使奉表请降，亦遣使降于晋；晋王命周德威安抚之。知裕心不自安，遂来奔，帝为之置归化军，以知裕为指挥使，凡军士自河朔来者皆隶之。辛丑，以万进为义昌留后。甲辰，改义昌为顺化军，以万进为节度使。'),
}
assert set(BATCH_258AX).issubset(byid)
BATCH_258AY = {
'v268-y-912-p13': ('晋军派兵进攻瓦桥关','戊申，周德威遣裨将李存晖等攻瓦桥关，'),
'v268-y-912-p15': ('吴军进攻宣州，李遇坚守逾月后开城投降','温怒，以淮南节度副使王檀为宣州制置使，数遇不入朝之罪，遣都指挥使柴再用帅升、润、池、歙兵纳檀于宣州，升州副使徐知诰为之副。遇不受代，再用攻宣州，踰月不克。'),
'v268-y-912-p18': ('蜀军讨平维州羌胡董琢叛乱','维州羌胡董琢反，蜀主遣保銮军使赵绰讨平之。'),
'v268-y-912-p20': None,
'v268-y-912-p22': ('晋军增兵围攻幽州，李嗣源攻取瀛州','周德威白晋王，以兵少不足攻城，晋王遣李存审将吐谷浑、契苾骑兵会之。李嗣源攻瀛州，刺史赵敬降。'),
'v268-y-912-p25': ('周德威在龙头冈击败燕军并生擒单廷珪','燕主守光遣其将单廷珪将精兵万人出战，与周德威遇于龙头冈。廷珪曰：「今日必擒周杨五以献。」杨五者，德威小名也。既战，见德威于陈，援枪单骑逐之，枪及德威背，德威侧身避之，奋檛反击廷珪坠马，生擒，置于军门。燕兵退走，德威引骑乘之，燕兵大败，斩首三千级。'),
'v268-y-912-p27': None,
'v268-y-912-p28': None,
'v268-y-912-p31': None,
'v268-y-912-p35': ('朱友珪与韩勍发动禁军政变，弑杀梁太祖','戊寅，友珪易服微行入左龙虎军，见统军韩勍，以情告之。勍亦见功臣宿将多以小过被诛，惧不自保，遂相与合谋。勍以牙兵五百人从友珪杂控鹤士入，伏于禁中，中夜斩关入，至寝殿，侍疾者皆散走。帝惊起，问：「反者为谁﹖」友珪曰：「非怹人也。」帝曰：「我固疑此贼，恨不早杀之。汝悖逆如此，天地岂容汝乎！」友珪曰：「老贼万段！」友珪仆夫冯廷谔刺帝腹，刃出于背。友珪自以败毡裹之，瘗于寝殿，秘不发丧。'),
'v268-y-912-p36': None,
'v268-y-912-p38': ('许州军士发动兵变，张厚杀死节度使韩建','时朝廷新有内难，中外人情匈忷忷。许州军士更相告变，匡国节度使韩建皆不之省，亦不为备；丙申，马步都指挥使张厚作乱，杀建，友珪不敢诘，甲辰，以厚为陈州刺史。'),
'v268-y-912-p40': ('杨师厚杀死潘晏并接管魏州军府','至是，师厚馆于铜台驿，潘晏入谒，执而杀之，引兵入牙城，据位视事。壬子，制以师厚为天雄节度使，徙周翰为宣义节度使。'),
'v268-y-912-p41': None,
'v268-y-912-p46': ('怀州戍兵溃乱剽掠，梁军击败叛军并处决刘重遇','八月，龙骧军三千人戍怀州者，溃乱东走，所过剽掠；戊子，遣东京马步军都指挥使霍彦威、左耀武指挥使杜晏球讨之，庚寅，击破乱军，执其都将刘重遇于鄢陵，甲午，斩之。'),
'v268-y-912-p47': ('朱友谦拒绝承认朱友珪，附晋并遭梁军征讨','护国节度使冀王朱友谦泣曰：「先帝数十年开创基业，前日变起宫掖，声闻甚恶，吾备位藩镇，心窃耻之。」友珪加友谦侍中、中书令，以诏书自辨，且征之。友谦谓使者曰：「所立者为谁﹖先帝晏驾不以理，吾且至洛阳问罪，何以征为！」戊戌，以侍卫诸军使韩勍为西面行营招讨使，督诸军讨之。友谦以河中附于晋以求救，九月，丁未，以感化节度使康怀贞为河中都招讨使，更以韩勍副之。'),
'v268-y-912-p48': None,
'v268-y-912-p49': None,
'v268-y-912-p50': None,
'v268-y-912-p51': None,
}
assert set(BATCH_258AY).issubset(byid)
BATCH_258AZ = {
'v268-y-912-p52': None,
'v268-y-912-p53': ('杨师厚率精兵入洛阳震慑朱友珪，随后返魏州','师厚将行，其腹心皆谏曰：「往必不测。」师厚曰：「吾知其为人，虽往，如我何！」乃帅精兵万余人，渡河趣洛阳，友珪大惧。丁亥，至都门，留兵于外，与十余人入见，友珪喜，甘言逊词以悦之，赐与巨万。癸巳，遣还。'),
'v268-y-912-p54': ('赵军攻取宗城后，杨师厚设伏大破来军','十一月，赵将王德明将兵三万掠武城，至于临清，攻宗城，下之。癸丑，杨师厚伏兵唐店，邀击，大破之，斩首五千余级。'),
'v268-y-912-p56': ('吴楚在岳州、荆南交战，吴军派兵屯吉州声援','吴淮南节度副使陈璋等将水军袭楚岳州，执刺史苑玫；楚王殷遣水军都指挥使杨定真救岳州。璋等进攻荆南，高季昌遣其将倪可福拒之。吴恐楚人救荆南，遣抚州刺史刘信帅江、抚、袁、吉、信五州兵屯吉州，为璋声援。'),
'v268-y-912-p57': ('蜀军攻取岐国文州','十二月，戊寅，蜀行营都指挥使王宗汾攻岐文州，拔之，守将李继夔走。'),
'v268-y-912-p60': ('高季昌率军进攻襄州，被孔勍击败','高季昌出兵，声言助梁伐晋，进攻襄州，山南东道节度使孔勍击败之。'),
'v268-y-912-p64': None,
'v268-y-912-p65': None,
'v268-y-912-p67': None,
'v268-y-912-p68': None,
'v268-y-912-p69': ('袁象先率禁军攻入宫中，朱友珪自尽，洛阳发生大掠','庚寅旦，袁象先等帅禁兵数千人突入宫中。友珪闻变，与妻张氏及冯廷谔趋北垣楼下，将踰城，自度不免，令廷谔先杀妻，后杀己，廷谔亦自刭。诸军十余万大掠都市，百司逃散，中书侍郎、同平章事杜晓、侍讲学士李珽皆为乱兵所杀，门下侍郎、同平章事于兢、宣政使李振被伤。至晡乃定。'),
'v268-y-912-p71': None,
'v268-y-912-p73': None,
'v268-y-912-p80': None,
'v268-y-912-p81': ('吴军出千秋岭攻打吴越衣锦军，吴越派军救援并袭击东洲','吴行营招讨使李涛帅众二万出千秋岭，攻吴越衣锦军。吴越王镠以其子湖州刺史传瓘为北面应援都指挥使以救之，睦州刺史传褄为招讨收复都指挥使，将水军攻吴东洲以分其兵势。'),
'v268-y-912-p83': None,
'v268-y-912-p84': None,
'v268-y-912-p85': None,
'v268-y-912-p86': None,
'v268-y-912-p87': ('梁军大举侵掠赵境，攻取下博并逼近沧州','杨师厚与刘守奇将汴、滑、徐、兖、魏、博、邢、洺之兵十万大掠赵境，师厚自柏乡入攻土门，趣赵州，守奇自贝州入趣冀州，所过焚掠。庚戌，师厚至镇州，营于南门外，燔其关城。壬子，师厚自九门退军下博，守奇引兵与师厚会攻下博，拔之。晋将李存审、史建瑭戍赵州，兵少，赵王告急于周德威。德威遣骑将李绍衡会赵将王德明同拒梁军。师厚、守奇自弓高渡御河而东，逼沧州，张万进惧，请迁于河南；师厚表徙万进镇青州，以守奇为顺化节度使。'),
}
assert set(BATCH_258AZ).issubset(byid)
BATCH_258BA = {
'v268-y-912-p88': None,
'v268-y-912-p89': None,
'v268-y-912-p95': None,
'v268-y-912-p96': None,
'v268-y-912-p97': ('蜀太子元膺发动兵变，率军攻杀唐道袭并在成都交战','戊申，徐瑶、常谦与怀胜军使严璘等各帅所部兵奉太子攻道袭。至清风楼，道袭引屯营兵出拒战；道袭中流矢，逐至城西，斩之。杀屯营兵甚众，中外惊扰。'),
'v268-y-912-p98': None,
'v268-y-912-p100': None,
'v268-y-912-p103': ('楚军进攻吴国鄂州，吴军出兵救援后楚军撤退','楚宁远节度使姚彦章将水军侵吴鄂州，吴以池州团练使吕师造为水陆行营应援使，未至，楚兵引去。'),
'v268-y-912-p105': None,
'v268-y-912-p106': ('吴越军进攻常州，与吴军在无锡夹击交战并获胜','吴越王镠遣其子传瓘、传褄及大同节度使传瑛攻吴常州，营于潘葑。徐温曰：「浙人轻而怯，」帅诸将倍道赴之。至无锡，黑云都将陈佑言于温曰：「彼谓吾远来罢倦，未能决战，请以所部乘其无备击之。」乃自怹道出敌后，温以大军当其前，夹攻之，吴越大败，斩获甚众。'),
'v268-y-912-p107': ('高季昌扩建战舰、城防并招聚亡命，增强荆南军备','高季昌造战舰五百艘，治城堑，缮器械，为攻守之具，招聚亡命，交通吴、蜀，朝廷浸不能制。'),
'v268-y-912-p108': None,
'v268-y-912-p111': None,
'v268-y-912-p112': None,
'v268-y-912-p113': ('梁军出兵侵扰庐州、寿州','以宁国节度使王景仁为淮南西北行营招讨应接使，将兵万余侵庐、寿。'),
'v269-y-913-p3': ('晋王率军押送刘仁恭父子自幽州班师，经定州、行唐','晋王欲自云、代归，赵王镕及王处直请由中山、真定趣井陉，王从之。庚辰，晋王发幽州，刘仁恭父子皆荷校于露布之下。守光父母唾其面而骂之曰：「逆贼，破我家至此！」守光俛首而已。甲申，至定州，舍于关城。丙戌，晋王与王处直谒北岳庙；是日，至行唐，赵王镕迎谒于路。'),
'v269-y-914-p1': None,
'v269-y-914-p4': ('荆南军焚毁蜀军浮桥，进攻夔州，被蜀军击败','高季昌以蜀夔、万、忠、涪四州旧隶荆南，兴兵取之，先以水军攻夔州。时镇江节度使兼侍中嘉王宗寿镇忠州，夔州刺史王成先请甲，宗寿但以白布袍给之。成先师之逆战，季昌纵火船焚蜀浮桥，招讨副使张武举铁焴拒之，船不得进。会风反，荆南兵焚溺死者甚众。季昌乘战舰，蒙以牛革，飞石中之，折其尾，季昌易小舟而遁。荆南兵大败，俘斩五千级。'),
'v269-y-914-p5': None,
'v269-y-914-p6': ('蜀国将镇江军军府迁至夔州','夏，四月，丙子，蜀主徙镇江军治夔州。'),
}
assert set(BATCH_258BA).issubset(byid)
BATCH_258BB = {
'v269-y-914-p7': None,
'v269-y-914-p8': ('刘崇景据袁州叛吴归楚，吴楚两军出兵讨伐','吴袁州刺史刘崇景叛，附于楚。崇景，威之子也。楚将许贞将万人援之，吴都指挥使迤再用、米志诚帅诸将讨之。'),
'v269-y-914-p9': ('楚军夜袭黄州，俘获刺史马邺并掠城而还','楚岳州刺史许德勋将水军巡边，夜分，南风暴起，都指挥使王环乘风趣黄州，以绳梯登城，径趣州署，执吴刺史马邺，大掠而还。'),
'v269-y-914-p10': None,
'v269-y-914-p11': None,
'v269-y-914-p12': ('晋军攻邢州，梁军出兵救援后晋军退兵','晋王既克幽州，乃谋入寇。秋，七月，会赵王镕及周德威于赵州，南寇邢州，李嗣昭引昭义兵会之。杨师厚引兵救邢州，军于漳水之东。晋军至张公桥，裨将曹进金来奔。晋军退，诸镇兵皆引归。八月，晋王还晋阳。'),
'v269-y-914-p15': ('王殷叛梁归吴，梁军围攻徐州并击退吴军援兵','帝以福王友璋为武宁节度使。前节度使王殷，友珪所置也，惧，不受代，叛附于吴；九月，命淮南西北面招讨应接使牛存节及开封尹刘鄩将兵讨之。冬，十月，存节等军于宿州。吴平卢节度使朱瑾等将兵救徐州，存节等逆击，破之，吴兵引归。'),
'v269-y-914-p16': ('蜀军多次击败南诏军，南诏部众在大渡河败退溺死','十一月，乙巳，南诏寇黎州，蜀主以夔王宗范、兼中书令宗播、嘉王宗寿为三招讨以击之。丙辰，败之于潘仓嶂，斩其酋长赵嵯政等；壬戌，又败之于山口城；十二月，乙亥，破其武侯岭十三寨；辛巳，又败之于大渡河，俘斩数万级，蛮争走渡水，桥绝，溺死者数万人。'),
'v269-y-914-p17': ('蜀军攻取岐国阶州、固镇及长城关','癸未，蜀兴州刺史兼北路制置指挥使王宗铎攻岐阶州及固镇，破细砂等十一寨，斩首四千级。甲申，指挥使王宗俨破岐长城关等四寨，斩首二千级。'),
'v269-y-915-p15': None,
'v269-y-915-p16': None,
'v269-y-915-p17': None,
'v269-y-915-p19': None,
'v269-y-915-p20': None,
'v269-y-915-p21': None,
'v269-y-915-p22': None,
'v269-y-915-p23': None,
'v269-y-915-p24': None,
'v269-y-915-p25': None,
'v269-y-915-p27': None,
'v269-y-915-p28': None,
'v269-y-915-p30': None,
'v269-y-915-p31': None,
'v269-y-915-p33': None,
'v269-y-915-p34': None,
'v269-y-915-p36': ('蜀宫失火，百尺楼所藏宝货尽被焚毁','十一月，己未夜，蜀宫火。自得成都以来，宝货贮于百尺楼，悉为煨烬。'),
'v269-y-915-p39': ('蜀军攻取秦州、阶州、成州、凤州，刘知俊解围归蜀','己巳，蜀王宗翰引兵出清泥岭，克固镇，与秦州将郭守谦战于泥阳川；蜀兵败，退保鹿台山。辛未，王宗绾等败秦州兵于金沙谷，擒其将李彦巢等，乘胜趣秦州。兴州刺史王宗铎克阶州，降其刺史李彦安。甲戌，王宗绾克成州，擒其刺史李彦德。蜀军至上染坊，秦州节度使李继崇遣其子彦秀奉牌印迎降。宗绛入秦州，表排陈使王宗俦为留后。刘知俊攻霍彦威于邠州，半岁不克，闻秦州降蜀，知俊妻子皆迁成都；知俊解围还凤翔，终惧及祸，夜帅亲兵七十人，斩关而出，庚辰，奔于蜀军。王宗绾自河池、两当进兵，会王宗瑶攻凤州，癸未，克之。'),
'v269-y-915-p40': ('岐将温昭图率耀、鼎二州归降后梁','岐义胜节度使、同平章事李彦韬知岐王衰弱，十二月，举耀、鼎二州来降。'),
'v269-y-915-p41': None,
'v269-y-915-p0': None,
'v269-y-915-p3': ('梁军越河进驻魏博，借杨师厚死后调整镇将向魏军示威','遣开封尹刘鄩将兵六万自白马济河，以讨镇、定为名，实张形势以胁之。'),
'v269-y-915-p4': ('魏博军变，叛军焚掠并围攻金波亭，继而攻入牙城挟持贺德伦','魏兵相与谋曰：「朝廷忌吾军府强盛，欲设策使之残破耳。吾六州历代藩镇，兵未尝远出河门，一旦骨肉流离，生不如死。」是夕，军乱，纵火大掠，围金波亭，王彦章斩关而走。诘旦，乱兵入牙城，杀贺德伦之亲兵五百人，劫德置楼上。'),
'v269-y-915-p5': None,
'v269-y-915-p7': None,
'v269-y-915-p8': ('晋军应魏博军之请出兵，攻入魏县并与梁军隔河对峙','晋王得贺德伦书，命马步副总管李存审自赵州进据临清。五月，存审至临清，刘鄩屯洹水。贺德伦复遣使告急于晋，晋王引大军自黄泽岭东下，与存审会于临清，犹疑魏人之诈，按兵不进。'),
'v269-y-915-p9': None,
'v269-y-915-p10': None,
'v269-y-915-p11': None,
'v269-y-915-p12': ('岐军围攻邠州，霍彦威坚守拒战','岐王遣彰义节度使刘知俊围邠州，霍彦威固守拒之。'),
'v269-y-915-p13': None,
}
assert set(BATCH_258BB).issubset(byid)
BATCH_258BC = {
'v269-y-916-p1':None,
'v269-y-916-p3':('吴国宿卫将马谦、李球劫持吴王并发兵讨徐知训，朱瑾平乱处决二人','二月，辛丑夜，吴宿卫将马谦、李球劫吴王登楼，发库兵讨徐知训；知训将出走，严可求曰：「军城有变，公先弃众自去，众将何依！」知训乃止。众犹疑惧，可求阖户而寝，鼾息闻于外，府中稍安。壬寅，谦等陈于天兴门外，诸道副都统朱瑾自润州至，视之，曰：「不足畏也。」返顾外众，举手大呼，乱兵皆溃，擒谦、球，斩之。'),
'v269-y-916-p4':('晋梁军在魏县交战，晋军大破刘鄩军','晋王乃留副总管李存审守营，自劳军于贝州，声言归晋阳。鄩闻之，奏请袭魏州，帝报曰：「今扫境内以属将军，社稷存亡，系兹一举，将军勉之！」鄩令澶州刺史杨延直引兵万人会于魏州，延直夜半至城南，城中选壮士五百潜出击之，延直不为备，溃乱而走。诘旦，鄩自莘县悉众至城东，与延直余众合，李存审引营中兵踵其后，李嗣源以城中兵出战，晋王亦自贝州至，与嗣源当其前。鄩见之，惊曰：「晋王邪！」引兵稍却，晋王蹑之，至故元城西，与李存审遇。晋王为方陈于西北，存审为方陈于东南，鄩为圆陈于其中间，四面受敌；合战良久，梁兵大败，鄩自变量十骑突围走。梁步卒凡七万，晋兵环而击之，败卒登木，木为之折，追至河上，杀溺殆尽。鄩收散卒自黎阳渡河，保滑州。'),
'v269-y-916-p5':('梁军进攻晋阳，晋军援军抵达后击退梁军','匡国节度使王檀密疏请发关西兵袭晋阳，帝从之，发河中、陕、同华诸镇兵合三万，出阴地关，奄至晋阳城下，昼夜急攻；城中无备，发诸司丁匠及驱市人乘城拒守，城几陷者数四，张承业大惧。代北故将安金全退居太原，往见承业曰：「晋阳根本之地，若失之，则大事去矣。仆虽老病，忧兼家国，请以库甲见授，为公击之。」承业即与之。金全帅其子弟及退将之家得数百人，夜，出北明，击梁兵于羊马城内；梁兵大惊，引却。昭义节度使李嗣昭闻晋阳有寇，遣牙将石君立将五百骑救之；君立朝发上党，夕至晋阳。梁兵扼汾河桥，君立击破之，径至城下大呼曰：「昭义侍中大军至矣。」遂入城。夜，与安金全等分出诸门击梁兵，梁兵死伤什二三。诘朝，王檀引兵大掠而还。'),
'v269-y-916-p6':None,
'v269-y-916-p7':('晋军攻取卫州、惠州','三月，乙卯朔，晋王攻卫州，壬戌，刺史米昭降之。又攻惠州，刺史靳绍走，擒斩之，复以惠州为磁州。'),
'v269-y-916-p8':('刘鄩率梁军驻屯黎阳','上屡召刘鄩不至，己巳，即以鄩为宣义节度使，使将兵屯黎阳。'),
'v269-y-916-p10':('李霸部兵变，攻打宫门并被杜晏球平定','刘鄩既败，河南有恐，鄩复不应召，由是将卒皆摇心。帝遣捉生都指挥使李霸帅所部千人戍杨刘，癸卯，出宋门，其夕，复自水门入，大噪，纵火剽掠，攻建国门，帝登楼拒战。龙骧四军都指挥使杜晏球以五百骑屯球场，贼以油沃幕，长木揭之，欲焚楼，势甚危；晏球于门隙窥之，见贼无甲，冑乃出骑击之，决力死战，俄而贼溃走。帝见骑兵击贼，呼日：「非吾龙骧之士乎，谁为乱首﹖」晏球曰：「乱者惟李霸一都，余军不动。陛下但帅控鹤守宫城，迟明，臣必破之。」既而晏球讨乱者，阖营皆族之，以功除单州刺史。'),
'v269-y-916-p12':('晋军围攻邢州，梁军援军转而投降晋军','六月，晋人攻邢州，保义节度使阎宝拒守；帝遣捉生都指挥使张温将兵五百救之，温以其众降晋。'),
'v269-y-916-p14':None,
'v269-y-916-p15':('润州牙将周郊发动兵变并杀死秦师权，后被陈佑等讨杀','甲子，吴润州牙将周郊作乱，入府，杀大将秦师权等，大将陈佑等讨斩之。'),
'v269-y-916-p17':('蜀军分别出凤州、秦州两路伐岐','丙午，蜀主以王宗绾为东北面都招讨，集王宗翰、嘉王宗寿为第一、第二招讨，将兵十万出凤州；以王宗播为西北面都招讨，武信军节度使刘知俊、天雄节度使王宗俦、匡国军使唐文裔为第一、第二、第三招讨，将兵十二万出秦州，以伐岐。'),
'v269-y-916-p18':('晋军攻取相州及邢州','晋王自将攻邢州，昭德节度使张筠弃相州走；晋人复以相州隶天雄军，以李嗣源为刺史。晋王遣人告阁宝以相州已拔，又遣张温帅援兵至城下谕之，宝举城降；晋王以宝为东南面招讨使，领天平节度使、同平章事；以李存审为安国节度使，镇邢州。'),
'v269-y-916-p19':('契丹攻取蔚州并围攻云州，李存璋坚守拒敌','契丹王阿保机帅诸部兵三十万，号百万，自麟、胜攻晋蔚州，陷之，虏振武节度使李嗣本。遣使以木书求货于大同防御使李存璋，存璋斩其使；契丹进攻云州，存璋悉力拒之。'),
'v269-y-916-p21':('晋军攻取沧州，守将毛璋投降','晋人以兵逼沧州，顺化节度使戴思远弃城奔东都；沧州将毛璋据城降晋，晋王命李嗣源将兵镇抚之，嗣源遣璋诣晋阳。晋王徙李存审为横海节度使，镇沧州，以嗣源为安国节度使。'),
'v269-y-916-p22':None,
'v269-y-916-p23':('晋军围困贝州逾年，城中断粮，守军投降后被杀三千','晋人围贝州踰年，张源德闻河北诸州皆为晋有，欲降；谋于其众，众以穷而后降，恐不免死，不从；共杀源德，婴城固守。城中食尽，噉人为粮，乃谓晋将曰：「出降惧死，请擐甲执兵而降，事定而释之。」晋将许之，其众三千出降，既释甲，围而杀之，尽殪。晋王以毛璋为贝州刺史。于是河北皆入于晋，惟黎阳为梁守。'),
'v269-y-916-p25':('吴军讨伐光州兵变，叛将王言弃城逃走','吴光州将王言杀刺史载肇，吴王遣楚州团练使李厚讨之。庐州观察使张崇不俟命，引兵趣光州，言弃城走。以李厚权知光州。'),
'v269-y-916-p27':('王檀遭群盗袭杀，裴彦率军平定乱兵','天平节度使兼中书令琅邪忠毅王王檀，多募群盗，置巾长下为亲兵，己卯，盗乘檀无备，突入府杀檀。节度副使裴彦帅府兵讨诛之，军府由是获安。'),
'v269-y-916-p28':('蜀军分路攻岐，攻取宝鸡、进至陇州并围攻凤翔','冬，十月，甲申，蜀王宗绾等出大散关，大破岐兵，俘斩万计，遂取宝鸡。己丑，王宗播等出故关，至陇州。丙寅，保胜节度使兼侍中李继岌畏岐王猜忌，帅其众二万，弃陇州奔于蜀军。蜀兵进攻陇州，以继岌为西北面行营第四招讨。刘知俊会王宗绾等围凤翔，岐兵不出。会大雪，蜀主召军还。'),
}
assert set(BATCH_258BC).issubset(byid)
