 ('-a','朱延寿围攻寿州，柴再用促成贾公铎、冯敬章投降','淮南将朱延寿奄至靳州，围其城。大将贾公铎方猎，不得还，伏兵林中，命勇士二人衣羊皮夜入延寿所，掠羊群，潜入城，约夜半开门举火为应，复衣皮反命。公铎如期引兵至城南，门中火举，力战，突围而入。延寿惊曰：「吾常恐其溃围而出，反溃围而入，如此，城安可猝拔！」乃白行密，求军中与公铎有旧者持誓书金帛往说之，许以婚。寿州团练副使柴再用请行，临城与语，为陈利害。数日，公铎及刺史冯敬章请降。'),
