split_event('v261-y-899-p22', [
 ('-a','李唐攻道州，被蔡结伏兵击败','马殷遣其将李唐攻道州，蔡结聚群蛮，伏兵于隘以击之，大破唐兵。'),
 ('-b','李唐放火烧林击散群蛮，攻取道州并斩杀蔡结','唐曰：「蛮所恃者山林耳，若战平地，安能败我！」乃命因风燔林，火烛天地，群蛮惊遁，遂拔道州，擒结，斩之。')])
split_event('v261-y-899-p23', [
 ('-a','李嗣昭攻取泽州、天井关并任命刺史','八月，丙寅，李嗣昭引兵至潞州城下，分兵攻泽州。己巳，汴将刘閗弃泽州走，河东兵进拔天井关，以李孝璋为泽州刺史。'),
 ('-b','李嗣昭围困潞州，迫使贺德伦弃城逃走','贺德伦闭城不出，李嗣昭日以铁骑环其城，捕刍牧者，附城三十里禾黍皆刈之。乙酉，德伦等弃城宵遁，趣壶关'),
 ('-c','李存审设伏击败逃出潞州的贺德伦部，葛从周退兵','河东将李存审伏兵邀击之，杀获甚众。葛从周以援兵至，闻德伦等已败，乃还。')])
split_event('v261-y-899-p26', [
 ('-a','台蒙、王绾率淮南军攻取密州交还王师范','冬，十月，行密遣海州刺史台蒙、副使王绾将兵助之，拔密州，归于师范'),
 ('-b','王绾设伏击败攻沂州未克后撤退的淄青军','将攻沂州，先使觇之，曰：「城中皆偃旗息鼓。」绾曰：「此必有备，而救兵近，不可击也。」诸将曰：「密已下矣，沂何能为！」绾不能止，乃伏兵林中以待之。诸将攻沂州不克，救兵至，引退；州兵乘之，绾发伏击败之。')])
split_event('v261-y-899-p29', [
 ('-a','李琼攻取郴州并斩杀刺史陈彦谦','马殷遣其将李琼攻郴州，执陈彦谦，斩之；'),
 ('-b','李琼进攻连州，鲁景仁自杀后湖南平定','进攻连州，鲁景仁自杀，湖南皆平。')])
split_event('v262-y-900-p6', [
 ('-a','葛从周攻取德州并斩杀刺史傅公和','五月，庚寅，拔德州，斩刺史傅公和；'),
 ('-b','葛从周率军围攻沧州','己亥，围刘守文于沧州。'),
 ('-c','周德威率五千骑攻刑、洺州以援救沧州','仁恭复遣使卑辞厚礼求援于河东，李克用遣周德威将五千骑出黄泽，攻刑、洺以救之。')])
split_event('v262-y-900-p10', [
 ('-a','葛从周击败救援沧州的刘仁恭军并斩首三万','刘仁恭将幽州兵五万救沧州，营于干宁军，葛从周留张存敬、氏叔琮守沧州寨，自将精兵逆战于老嵵堤，大破仁恭，斩首三万级，仁恭走保瓦桥。'),
 ('-b','李嗣昭率五万军攻邢、洺并在内丘击败汴军','秋，七月，李克用复遣都指挥使李嗣昭将兵五万攻邢、洺以救仁恭，败汴军于内丘。')])
split_event('v262-y-900-p13', [
 ('-a','李嗣昭在沙门河击败汴军并攻取洺州','八月，李嗣昭又败汴军于沙门河，进攻洺州。乙丑，朱全忠引兵救之，未至，嗣昭拔洺州，擒刺史朱绍宗。'),
 ('-b','朱全忠派葛从周率军反击李嗣昭','全忠命葛从周将兵击嗣昭。')])
split_event('v262-y-900-p21', [
 ('-a','李琼率小队夜袭秦城，擒获王建武','彦晖遣李琼将骑六十、步兵三百袭秦城，中宵，踰垣而入，擒王建武，比明，复还'),
 ('-b','李琼率湖南军攻破可璠营寨并围攻桂州','可璠犹未之信；斩其首；斩其首，投壁中，桂人震恐。琼因勒兵击之，擒可璠，降其将士二千，皆杀之。引兵趣桂州，自秦城以南二十余壁皆望风奔溃，遂围桂州；数日，士政出降，桂、宜、岩、柳、象五州皆降于湖南。')])
split_event('v262-y-900-p22', [
 ('-a','张存敬攻下二十城并转兵西攻易定','张存敬攻刘仁恭，下二十城，将自瓦桥趣幽州，道泞不能进；乃引兵西攻易定'),
 ('-b','张存敬攻取祁州并斩杀刺史杨约','辛巳，拔祁州，杀刺史杨约。')])
split_event('v262-y-900-p24', [
 ('-a','王处直率军在沙河迎战张存敬，义武军大败','郜乃遣处直逆战于沙河，易定兵大败，死者过半，余众拥处直奔还。甲申，王郜弃城奔晋阳，军中推处直为留后。'),
 ('-b','朱全忠围攻定州后与王处直议和撤军','存敬进围定州，丙申，朱全忠至城下；处直登城呼曰：「本道事朝廷甚忠，于公未尝相犯，何为见攻﹖」全忠曰：「何故附河东﹖」对曰：「吾兄与晋王同时立勋，封疆密迩，且婚姻也，修好往来，乃常理耳；请从此改图。」全忠许之。乃归罪于梁汶而族之，以谢全忠，以缯帛十万犒师；全忠乃还，仍为处直表求节钺。')])
split_event('v262-y-900-p26', [
 ('-a','李嗣昭攻取怀州','李克用遣李嗣昭将步骑三万下太行，攻怀州，拔之'),
 ('-b','李嗣昭进攻河阳，遭阎宝援军激战后退兵','进攻河阳。河阳留后侯言不意其至，狼狈失据，嗣昭坏其羊马城。会佑国军将阎宝引兵救之，力战于壕外，河东兵乃退。')])
split_event('v262-y-901-p9', [
 ('-a','张存敬率军袭取绛州，刺史陶建钊投降','庚戌，绛州刺史陶建钊降之；'),
 ('-b','张存敬攻取晋州并屯兵阻断河东援军','壬子，晋州刺史张汉瑜降之。全忠遣其将侯言守晋州，何絪守绛州，屯兵二万以扼河东援兵之路。')])
split_event('v262-y-901-p18', [
 ('-a','氏叔琮率军攻入河东，攻取泽州并逼近晋阳','叔琮入天井关，进军昂车。辛亥，沁州刺史蔡训以城降。河东都将盖璋诣候言降，即令权知沁州。壬子，叔琮拔泽州，李存璋弃城走。叔琮进攻潞州，昭义节度使孟迁降之。河东屯将李审建、王周将步军一万、骑二千诣叔琮降；叔琮进趣晋阳。'),
 ('-b','张归厚率军进抵辽州，刺史张鄂投降','张归厚引兵至辽州，丁巳，辽州刺史张鄂降。'),
 ('-c','白奉国会合成德军攻取承天军','别将白奉国会成德兵自井陉入，己未，拔承天军，与叔琮烽火相应。')])
