split_event('v266-y-907-p16', [
 ('-a','李思安率军攻入幽州，焚掠沿途并兵临幽州城下，刘守光守城击败之','李思安引兵入其境，所过焚荡无余。夏，四月，己酉，直抵幽州城下。仁恭犹在大安山，城中无备，几至不守。守光自外引兵入，登城拒守；又出兵与思安战，思安败退。'),
 ('-b','刘守光自称节度使，派兵攻取大安山并俘虏刘仁恭','守光遂自称节度使，令部将李小喜、元行钦将兵攻大安山。仁恭遣兵拒战，为小喜所败。虏仁恭以归，囚于别室。仁恭将佐及左右，凡守光素所恶者皆杀之。')])
split_event('v266-y-907-p19', [
 ('-a','钱传瓘避开卢佶水军、间道突袭温州并擒杀卢佶','卢售闻钱传褄等将至，将水军拒之于青澳。钱传瓘曰：「售之精兵尽在于此，不可与战。」乃自安固舍舟，间道袭温州。戊午，温州溃，擒售斩之。'),
 ('-b','钱传褄、钱传瓘奉命转兵讨伐处州卢约','吴王镠以都监使吴璋为温州制置使，命传褄等移兵讨卢约于处州。')])
