split_event('v267-y-909-p57', [
 ('-a','刘知俊围攻灵州，梁军出兵救援','岐王欲取灵州以处刘知俊，且以为牧马之地，使知俊自将兵攻之。朔方节度使韩逊告急；诏镇国节度使康怀贞、感化节度使寇彦卿将兵攻邠宁以救之。'),
 ('-b','康怀贞等攻取宁、衍二州及庆州南城，刘知俊解灵州之围','怀贞等所向皆捷，克宁、衍二州，拔庆州南城，刺史李彦广出降。游兵侵掠至泾州之境，刘知俊闻之，十二月，己丑，解灵州围，引兵还。'),
 ('-c','刘知俊设伏升平击败康怀贞军，李德遇等部覆没','帝急召贞等还，遣兵迎援于三原青谷；怀贞等还，至三水，知俊遣兵据险邀之，左龙骧军使寿张王彦章力战，怀贞等乃得过。怀贞与裨将李德遇、许从实、王审权分道而行，皆与援兵不相值，至升平，刘知俊伏兵山口，怀贞大败，仅以身免，德遇等军皆没。')])

