 ('v266-y-907-p57','v266-y-907-p48','晋周德威壁于高河，康怀贞遣亲骑都头秦武将兵击之，武败。'),
 ('v266-y-907-p58','v266-y-907-p48','丁巳，帝以亳州刺史李思安代怀贞为潞州行营都统，黜怀贞为行营都虞候。思安将河北兵西上，至潞州城下，更筑重城，内以防奔突，外以拒援兵，谓之夹寨。调山东民馈军粮，德威日以轻骑抄之，思安乃自东南山口筑甬道，属于夹寨。﹖德威与诸将互往攻之，排墙填堑，一昼夜间数十发，梁兵疲于奔命。夹寨中出刍牧者，德威辄抄之，于是梁兵闭壁不出。'),
