 ('v265-y-905-p4','v265-y-905-p0','全忠围寿州，州人闭壁不出。全忠乃自霍丘引归，二月辛卯，至大梁。'),
 ('v265-y-905-p37','v265-y-905-p36-c','匡凝至广陵，杨行密戏之曰：「君在镇，岁以金帛输全忠，今败，乃归我乎﹖」匡凝曰：「诸侯事天子，岁输贡赋乃其职也，岂输贼秋！今日归公，正以不从贼故耳。」行密厚遇之。'),
 ('v265-y-905-p40','v265-y-905-p31','王宗贺等攻冯行袭，所向皆捷。丙子，行袭弃金州，奔均州；其将全师朗以城降。王建更师朗姓名曰王宗朗，补金州观察使，割渠、巴、开三州以隶之。'),
