 ('v264-y-903-p37','v264-y-903-p36-b','张训闻茂章去，谓诸将曰：「汴人将至，何以御之﹖」诸将请焚城大掠而归。训曰：「不可。」封府库，植旗帜于城上，遣羸弱居前，自以精兵殿其后而去。全忠遣左踏白指挥使王檀攻密州，既至，望旗帜，数日乃敢入城；见府库城邑皆完，遂不复追。训全军而还。全忠以檀为密州刺史。'),
 ('v264-y-903-p40','v264-y-903-p47-b','八月，戊辰朔，朱全忠留齐州刺史杨师厚攻青州，身归大梁。'),
