 ('v264-y-903-p18','淮南将李神福围鄂州，望城中积荻，谓监军尹建峰曰：「今夕为公焚之。」建峰未之信。时杜洪求救于朱全忠，神福遣部将秦皋乘轻舟至滠口，举火炬于树杪；洪以为救兵至，果焚荻以应之。'),
 ('v264-y-903-p23','杜洪求救于朱全忠，全忠遣其将韩勍将万人屯滠口，遣使语荆南节度使成汭、武安节度使马殷、武贞节度使雷彦威，令出兵救洪。汭畏全忠之强，且欲侵江、淮之地以自广，发舟师十万，沿江东下。汭作巨舰，三年而成，制度如府署，谓之「和舟载」，其余谓之「齐山」、「截海」、「劈浪」之类甚众。掌书记李珽谏曰：「今每舰载甲士千人，稻米位之，缓急不可动也。吴兵剽轻，难与角逐；武陵、长沙，皆吾雠也；岂得不为反顾之虑乎！不若遣骁将屯巴陵，大军与之对岸，坚壁勿战，不过一月，吴兵食尽自遁，鄂围解矣。」汭不听。'),
