    if continuation is None:
        candidate = byid[continuation_id]
        source = {'volume': candidate['volume'], 'year': candidate['year'], 'anchor': candidate['anchor'], 'quote': cue}
    else:
        source = continuation['sources'][0]
        events.remove(continuation)
