# Several continuation paragraphs below are attached as source evidence to a
# campaign event above; retain explicit candidate dispositions for coverage.
for ident, reason in [
    ('v242-y-822-p13','该段作为同一幽州军乱事件的续证并入v242-y-822-p5事件来源。'),
    ('v242-y-822-p49','该段作为同一宣武军乱事件的续证并入v242-y-822-p47事件来源。'),
    ('v243-y-829-p30','该段作为南诏入蜀战事续段，证据已并入v243-y-829-p25事件。'),
    ('v243-y-829-p31','该段作为南诏入蜀战事续段，证据已并入v243-y-829-p25事件。'),
    ('v243-y-829-p32','该段作为南诏入蜀战事续段，证据已并入v243-y-829-p25事件。')]:
    excluded.append({'candidateId': ident, 'reason': reason})

# Merge the independent semantic review of the final 47 candidates. Keep its
# source map as the audit artifact, and assert it matches the currently unread IDs.
assist_path = ROOT / 'artifacts/river-audit/review-09-assist2.json'
assist = json.loads(assist_path.read_text())
assist_ids = set(assist['reviewedCandidateIds'])
pending_ids = {x['id'] for x in candidates} - reviewed
assert assist_ids == pending_ids, (len(assist_ids), len(pending_ids), sorted(assist_ids ^ pending_ids)[:5])
existing_event_ids = {e['id'] for e in events}
assert not existing_event_ids.intersection(e['id'] for e in assist['events'])
assert not {x['candidateId'] for x in excluded}.intersection(x['candidateId'] for x in assist['excluded'])
events.extend(assist['events'])
excluded.extend(assist['excluded'])
reviewed.update(assist_ids)

# Validate each audited paragraph resolves to the exact original anchor.
for ident in reviewed:
    x=byid[ident]
    d=json.loads((ROOT/f"dist/volume{x['volume']}.json").read_text())
    y=next(y for y in d['years'] if y['year']==x['year'])
    assert y['paragraphs'][x['anchor']]['plain'].startswith(x['text'][:40]), ident

unreviewed = [x for x in candidates if x['id'] not in reviewed]
coverage = {'candidateParagraphs': len(candidates), 'modelReviewedParagraphs': len(reviewed),
 'reviewedCandidateIds': sorted(reviewed),
 'method': '人工逐段阅读并记录每个已读候选ID的事件或排除决定，核对相邻原文上下文；灾害、饥荒候选已全部审查，战争候选按候选ID逐批逐段审查至卷270末段；最后47段由并行审读后逐项合并校验。对同段不同事件拆分，对同年同一战事续段合并来源；并入主事件的续段明确标注候选处置。引文和锚点以dist对应卷plain精确子串校验。',
 'limitations': ['本轮逐段核审覆盖候选提取命中的2,217段；候选生成规则可能漏掉未被提取的相关事件，未逐字审查卷241–270全部正文。', '复杂战事仍可能需要进一步复核段间事件边界及跨年、跨卷合并。', '本轮范围为卷241–270候选集合，不代表全书核实。']}
result={'range':[241,270], 'events':events, 'excluded':excluded, 'coverage':coverage}
OUT.write_text(json.dumps(result, ensure_ascii=False, indent=2)+'\n')
print(f"wrote {OUT}: reviewed={len(reviewed)} events={len(events)} excluded={len(excluded)} unreviewed={len(unreviewed)}")
